 </>;
 if(sent)return <Panel><Icon name="checkmark-circle-outline" color={t.accent} size={42}/><Label style={{fontSize:26,fontWeight:'800',marginTop:16}}>Doručeno.</Label><Label muted style={{lineHeight:23,marginVertical:16}}>{recipient?.name} najde zprávu v Oznámení po přihlášení do svého místního účtu.</Label><Button title="Napsat další zprávu" onPress={reset}/><Button title="Zobrazit odeslané" secondary style={{marginTop:10}} onPress={()=>{reset();T('Odeslané');}}/></Panel>;
 if(review)return <View testID="bank-message-review"><Label style={{fontSize:25,fontWeight:'800',marginBottom:17}}>Připraveno k doručení.</Label><Panel><Row icon="person-outline" title={recipient?.name} sub={recipient?.auth?.email||'Místní účet · '+target.slice(-6)}/><Label muted style={{fontSize:12,lineHeight:20,marginTop:12}}>Od {BANK_SENDER} · {review.department}</Label><Label style={{fontSize:23,fontWeight:'800',marginTop:18}}>{review.title}</Label><Label selectable style={{lineHeight:24,marginTop:15}}>{review.body}</Label></Panel>{attachmentPreview(review)}<Label muted style={{fontSize:12,lineHeight:20,marginVertical:18}}>Doručí se pouze vybranému místnímu účtu. Odeslanou zprávu a přílohy již nelze změnit.</Label><Button title="Odeslat klientovi" icon="send-outline" onPress={send}/><Button title="Upravit zprávu" secondary style={{marginTop:10}} onPress={()=>R(null)}/></View>;
