 const titleStyle={fontSize:35,fontWeight:'700',letterSpacing:-1.5};
 function heading(kicker,title,action){return <View style={[s.between,{marginBottom:20}]}><View><Label muted style={{fontSize:11,fontWeight:'700',letterSpacing:2,marginBottom:7}}>{kicker}</Label><Label style={titleStyle}>{title}</Label></View>{action}</View>;}
 const quick=(icon,title,onPress)=><Pressable key={title} accessibilityRole="button" accessibilityLabel={title} onPress={onPress} style={{alignItems:'center',flex:1,gap:8}}><View style={[s.quick,{backgroundColor:t.panel,borderColor:t.border}]}><Icon name={icon} color={t.accent} size={23}/></View><Label style={{fontSize:12,fontWeight:'600',letterSpacing:-.2}}>{title}</Label></Pressable>;
 const home=()=> <><PromoBubble ui={ui3} onPress={()=>setTab('Promo')}/><HomeHeader u={u} ui={ui3} notificationsEnabled={data.notifications} onAccounts={()=>open('accounts')} onTiers={()=>open('tiers')} onNotifications={()=>open('notifications')}/>{!!u.pendingTransfers.length&&<Panel style={{marginBottom:18}}><Row icon="time-outline" title="Čekající platby" sub="Připsání podle zvoleného termínu" value={String(u.pendingTransfers.length)} onPress={()=>setTab('Platby')}/></Panel>}<Home5 u={u} data={data} ui={ui3} go={goV3} onOpen={openFromV3} renderCard={c=><CardArt card={c} name={u.name}/>} currency={currency} setCurrency={setCurrency} onTransaction={transaction=>open('transaction',{transaction})} onCommand={()=>setCommandOpen(true)}/></>;
 const promo=()=> <>
  <Pressable accessibilityRole="button" accessibilityLabel="Zpět na přehled" onPress={()=>setTab('Přehled')} style={{flexDirection:'row',alignItems:'center',gap:6,alignSelf:'flex-start',paddingVertical:9,marginBottom:19}}><Icon name="chevron-back" size={20} color={t.accent}/><Label style={{color:t.accent,fontWeight:'600'}}>Zpět na přehled</Label></Pressable>
  <Label muted style={{fontSize:10,fontWeight:'800',letterSpacing:1.6,marginBottom:10}}>ZENVAULT BENEFITS</Label>
  <Label accessibilityRole="header" style={{fontSize:24,fontWeight:'700',letterSpacing:-.7,lineHeight:30,marginBottom:22}}>Netflix nebo HBO Max Promo</Label>
  <LinearGradient colors={t.featureGradient} style={{padding:24,borderRadius:28,overflow:'hidden'}}>
   <View style={{width:50,height:50,borderRadius:18,backgroundColor:dark?'#2B4E6A':'#FFFFFF',justifyContent:'center',alignItems:'center',marginBottom:23}}><Icon name="play-outline" size={25} color={t.accent}/></View>
   <Label accessibilityRole="header" style={{fontSize:30,lineHeight:35,fontWeight:'800',letterSpacing:-1}}>Vyber si službu, která ti nejvíce sedí!</Label>
   <Label muted style={{fontSize:15,lineHeight:23,marginTop:15}}>Užij si měsíc prémiové zábavy na náš účet. V rámci výhod svého účtu Zenvault si můžeš vybrat měsíční předplatné Premium u Netflixu nebo HBO Max zdarma.</Label>
   <View style={{flexDirection:'row',flexWrap:'wrap',gap:8,marginTop:20}}>{['1 měsíc','Premium','0 Kč'].map(v=><View key={v} style={{paddingVertical:8,paddingHorizontal:13,borderRadius:20,backgroundColor:dark?'#29475F':'#FFFFFF'}}><Label style={{fontSize:12,fontWeight:'700',color:dark?'#9DD7FF':'#227FB5'}}>{v}</Label></View>)}</View>
  </LinearGradient>
  <Panel style={{marginTop:18,borderColor:t.accent}}><View style={{flexDirection:'row',alignItems:'center',gap:11,marginBottom:13}}><NetworkLogo network="Mastercard"/><Label style={{fontWeight:'700',flex:1}}>Exkluzivně se Zenvault Mastercard</Label></View><Label style={{lineHeight:22}}>Pro první měsíc zdarma musíš při uplatnění nabídky použít kartu Zenvault Mastercard.</Label><View style={{flexDirection:'row',alignItems:'center',gap:10,marginTop:14}}><NetworkLogo network="Visa"/><Label muted style={{fontSize:13,lineHeight:20,flex:1}}>Na karty Visa se toto promo nevztahuje.</Label></View></Panel>
  <Section title="Karta pro uplatnění"/>{eligibleCards.length?<Panel>{eligibleCards.map(c=><Row key={c.id} title={'Mastercard •••• '+c.last} sub={c.type+' · '+c.tier} right={promoCard?.id===c.id?<Icon name="checkmark-circle" color={t.accent}/>:null} onPress={()=>editUser(x=>({...x,promoCardId:c.id}))}/>)}</Panel>:<Panel><Label muted style={{lineHeight:22}}>Pro výběr služby potřebuješ aktivní Zenvault Mastercard s povolenými online platbami. Karty Visa nejsou způsobilé.</Label><Button title="Přejít na karty" secondary style={{marginTop:14}} onPress={()=>setTab('Karty')}/></Panel>}
  <Section title="Tvůj večer. Tvoje volba."/>
  <Label muted style={{lineHeight:22,marginBottom:18}}>Filmový maraton, nový seriál nebo chvíle jen pro sebe. Vyber si, kde strávíš svůj příští večer.</Label>
  {[{name:'Netflix',colors:['#171717','#090909'],accent:'#FF6374',tag:'JEŠTĚ JEDEN DÍL?',text:'Pro večery, kdy chceš objevovat nové příběhy a vybírat podle nálady.'},{name:'HBO Max',colors:['#171717','#090909'],accent:'#A7CDFF',tag:'UDĚLEJ SI FILMOVÝ VEČER.',text:'Pro chvíle, kdy se chceš ponořit do velkého příběhu a užít si zábavu naplno.'}].map(z=><View key={z.name} style={{marginBottom:16}}><LinearGradient colors={z.colors} start={{x:0,y:0}} end={{x:1,y:1}} style={{padding:23,borderRadius:25,borderWidth:2,borderColor:u.promoChoice===z.name?t.accent:'transparent'}}>
   <View style={s.between}><Text style={{color:t.mono?'#DDDDDD':z.accent,fontSize:10,fontWeight:'700',letterSpacing:1.3}}>{z.tag}</Text>{u.promoChoice===z.name&&<Icon name="checkmark-circle" color="#80D0FF"/>}</View>
   <ServiceLogo name={z.name}/><Text style={{color:'#D1D9E8',fontSize:13,fontWeight:'600',marginTop:5}}>Premium · 1 měsíc zdarma</Text><Text style={{color:'#C2CADB',fontSize:14,lineHeight:21,marginTop:16,marginBottom:21}}>{z.text}</Text>
   <Button title={u.promoChoice===z.name?'Vybráno: '+z.name:'Vybrat '+z.name} icon={u.promoChoice===z.name?'checkmark-outline':'arrow-forward-outline'} disabled={!promoCard} onPress={()=>{if(!promoCard)return fail('Promo vyžaduje Zenvault Mastercard.');editUser(x=>({...x,promoChoice:z.name,promoCardId:promoCard.id}));setToast('Výběr uložen: '+z.name+'.');}} style={{backgroundColor:t.button,borderColor:t.mono?'#535353':t.button}}/>
  </LinearGradient></View>)}
  {u.promoChoice&&<Panel style={{borderColor:t.accent,marginTop:3,marginBottom:7}}><View style={{flexDirection:'row',gap:11,alignItems:'center'}}><Icon name="checkmark-circle-outline" color={t.accent} size={28}/><View style={{flex:1}}><Label style={{fontWeight:'700',fontSize:16}}>Tvá volba: {u.promoChoice}</Label><Label muted style={{fontSize:12,lineHeight:18,marginTop:5}}>Výběr máš uložený. Můžeš ho kdykoliv změnit.</Label></View></View><Pressable accessibilityRole="button" onPress={()=>{editUser(x=>({...x,promoChoice:null}));setToast('Výběr byl zrušen.');}} style={{paddingTop:15,alignSelf:'flex-start'}}><Label style={{color:t.accent,fontWeight:'600',fontSize:13}}>Zrušit výběr</Label></Pressable></Panel>}
  <Section title="Co nabídka zahrnuje"/><Panel><Row icon="gift-outline" title="Měsíc Premium zdarma" sub="První měsíc při použití Zenvault Mastercard."/><Row icon="checkmark-circle-outline" title="Jedna nabídka, tvoje volba" sub="Vyber si Netflix, nebo HBO Max."/><Row icon="wallet-outline" title="Výhoda účtu Zenvault" sub="Výběr služby nic neodečte z tvého zůstatku."/></Panel>
  <Section title="Jak to funguje"/><Panel>{[['01','Vyber si svou službu','Vyber svou Zenvault Mastercard a ulož si službu, která tě osloví.'],['02','Zkontroluj svůj výběr','Zvolenou službu najdeš na této stránce. Výběr můžeš upravit.'],['03','Uplatnění nabídky','Uložení výběru samo o sobě předplatné neaktivuje. Aktivační pokyny zatím nejsou k dispozici.']].map(([n,title,text])=><View key={n} style={{flexDirection:'row',gap:13,paddingVertical:12}}><Label style={{fontWeight:'800',fontSize:13,color:t.accent,paddingTop:3}}>{n}</Label><View style={{flex:1}}><Label style={{fontWeight:'700',marginBottom:6}}>{title}</Label><Label muted style={{fontSize:13,lineHeight:21}}>{text}</Label></View></View>)}</Panel>
  <Section title="Dobré vědět"/><Panel><Label style={{fontWeight:'700',marginBottom:9}}>Mohu získat obě služby?</Label><Label muted style={{lineHeight:21,fontSize:13,marginBottom:19}}>V rámci této nabídky si vybíráš jednu z uvedených služeb na první měsíc zdarma. Podmínkou je použití Zenvault Mastercard; pro Visa nabídka neplatí.</Label><Label style={{fontWeight:'700',marginBottom:9}}>Co se stane po měsíci?</Label><Label muted style={{lineHeight:21,fontSize:13}}>Podmínky uplatnění a případného pokračování předplatného musí být uvedeny před aktivací. Samotným uložením výběru v Zenvault žádné předplatné nesjednáváš.</Label></Panel>
 </>;
 const payments=()=> <>{heading('VŠECHNO POD KONTROLOU','Platby')}<View style={{flexDirection:'row',gap:10,marginBottom:20}}><Button style={{flex:1}} title="Nová platba" icon="add" onPress={()=>goV3('transfer')}/><Button title="Vyžádat" secondary onPress={()=>goV3('requests')}/></View><Field label="Hledat v historii" placeholder="Obchodník, kategorie, poznámka" value={search} onChangeText={setSearch}/><Chips items={['Vše','Příjmy','Výdaje']} value={filter} onChange={setFilter}/><Section title="Historie" action="Exportovat" onPress={()=>share('Datum;Název;Částka;Měna;Stav;Předpokládané připsání\n'+filtered.map(x=>[x.date,x.name.replace(/[;\n]/g,' '),x.value/100,x.currency,paymentStatus(x),x.dueAt||''].join(';')).join('\n'))}/><Transactions items={filtered} hidden={data.hide} onPress={x=>open('transaction',{transaction:x})}/>{u.requests.length>0&&<><Section title="Žádosti o platbu"/><Panel>{u.requests.map(r=><Row key={r.id} icon="arrow-down-outline" title={money(r.amount,r.currency)} sub={r.note||'Vytvořená žádost'} onPress={()=>share('Žádost o platbu: '+money(r.amount,r.currency)+' pro '+u.name+'\n'+r.note)}/>)}</Panel></>}</>;
 const cardsPage=()=> <>{heading('STVOŘENÉ PRO VÁS','Vaše karty',<Pressable accessibilityLabel="Přidat kartu" onPress={()=>isUnlimitedTier(u.tier)?goV3(builderRoute(u.tier)):open('newCard',{}, {tier:u.tier,type:'Virtuální',network:'Mastercard',design:0})}><Icon name="add-circle-outline" size={30} color={t.accent}/></Pressable>)}<Chips items={u.cards.map((x,i)=>(i+1)+' · '+x.type+' '+x.last)} value={(Math.min(cardIndex,u.cards.length-1)+1)+' · '+card.type+' '+card.last} onChange={v=>setCardIndex(parseInt(v)-1)}/><View style={{marginTop:15}}><CardArt card={card} name={u.name}/></View><Pressable accessibilityRole="button" accessibilityLabel="Přidat do Apple Pay" onPress={applePayPreview} style={[s.button,{marginTop:17,backgroundColor:'#101015',gap:5}]}><Text style={{color:'#FFFFFF',fontSize:16,fontWeight:'600'}}>Přidat do</Text><Icon name="logo-apple" color="#FFFFFF" size={21}/><Text style={{color:'#FFFFFF',fontSize:18,fontWeight:'600'}}>Pay</Text></Pressable><Label muted style={{textAlign:'center',fontSize:11,marginTop:7}}>Náhled Apple Pay · bez přidání do Peněženky</Label><View style={{flexDirection:'row',marginVertical:23}}>{quick(card.frozen?'sunny-outline':'snow-outline',card.frozen?'Odmrazit':'Zmrazit',()=>{updateCard('frozen',!card.frozen);setToast(card.frozen?'Karta je aktivní.':'Karta byla zmrazena.');})}{quick('options-outline','Design',()=>open('cardDesign',{}, {design:card.design}))}{quick('speedometer-outline','Limit',()=>open('limit',{}, {amount:String(card.limit/100)}))}</View><Panel><Row icon="globe-outline" title="Online platby" sub="Platby na internetu" right={<Switch accessibilityLabel="Online platby" value={card.online} onValueChange={v=>updateCard('online',v)} trackColor={{true:t.accent}}/>}/><Row icon="radio-outline" title="Bezkontaktní platby" right={<Switch accessibilityLabel="Bezkontaktní platby" value={card.contactless} onValueChange={v=>updateCard('contactless',v)} trackColor={{true:t.accent}}/>}/><Row icon="shield-checkmark-outline" title="Stav karty" value={card.frozen?'Zmrazená':'Aktivní'}/><Row icon="speedometer-outline" title="Denní limit" value={money(card.limit)} onPress={()=>open('limit',{}, {amount:String(card.limit/100)})}/></Panel><Button title="Card Controls a jednorázové karty" secondary style={{marginTop:16}} onPress={()=>goV3('controls')}/><Button title="Lokální karetní platba" secondary style={{marginTop:9}} onPress={()=>goV3('cardpay')}/><Button title="Card Gallery" secondary style={{marginTop:9}} onPress={()=>goV3('gallery')}/><Section title="Ink Collection" action="Všechny tarify" onPress={()=>open('tiers')}/><Label muted style={{lineHeight:21}}>Každý plán má svůj vlastní styl, včetně trojice Ultra MAX. Vyšší kolekce najdeš v Card Builderu. Hologram Limited je s Business, Unlimited MAX a Prestige zdarma. Festivalovou edici Zenvault × Rolling Loud odemkneš za 1 000 bodů.</Label></>;
 const savings=()=> <>{heading('MALÉ KROKY. VELKÉ PLÁNY.','Spoření')}<Panel style={{padding:24}}><Label muted>Celkem v cílech</Label><Label style={[titleStyle,{marginTop:9}]}>{data.hide?'••••':money(u.goals.reduce((a,g)=>a+g.saved,0))}</Label><Label muted style={{fontSize:12,marginTop:10}}>Vlastní prostor pro všechno, na čem záleží.</Label></Panel><Section title="Vaše cíle" action="+ Nový cíl" onPress={()=>open('newGoal')}/>{u.goals.length===0&&<Panel><Label muted>Vytvořte si první cíl a začněte odkládat.</Label></Panel>}{u.goals.map(g=><Panel key={g.id} style={{marginBottom:13}}><View style={s.between}><View style={{flexDirection:'row',alignItems:'center',gap:10}}><Icon name={g.icon||'sparkles-outline'} color={t.accent}/><Label style={{fontWeight:'700',fontSize:18}}>{g.name}</Label></View><Label muted>{Math.min(100,Math.round(g.saved/g.target*100))}%</Label></View><View style={[s.track,{backgroundColor:t.soft,marginVertical:19}]}><View style={{height:7,borderRadius:8,backgroundColor:t.accent,width:Math.min(100,g.saved/g.target*100)+'%'}}/></View><Label muted style={{fontSize:12,marginBottom:16}}>{data.hide?'••••':money(g.saved)+' z '+money(g.target)}</Label><View style={{flexDirection:'row',gap:10}}><Button title="Odložit" style={{flex:1}} onPress={()=>open('goalDeposit',{id:g.id,name:g.name})}/><Button title="Vybrat" secondary style={{flex:1}} onPress={()=>open('goalWithdraw',{id:g.id,name:g.name})}/></View></Panel>)}</>;
 const insights=()=>{const cats={};spend.forEach(x=>cats[x.category]=(cats[x.category]||0)-x.value);return <>{heading('VÁŠ FINANČNÍ RYTMUS','Přehledy')}<Panel><Label muted>Výdaje · {new Date().toLocaleDateString('cs-CZ',{month:'long',year:'numeric'})}</Label><Label style={[titleStyle,{marginVertical:13}]}>{data.hide?'••••':money(totalSpend)}</Label><View style={[s.track,{backgroundColor:t.soft,marginTop:8}]}><View style={{height:7,borderRadius:8,width:Math.min(100,totalSpend/u.budget*100)+'%',backgroundColor:totalSpend>u.budget?'#EF786F':t.accent}}/></View><Row title="Měsíční rozpočet" value={money(u.budget)} onPress={()=>open('budget',{}, {amount:String(u.budget/100)})}/><Label muted style={{fontSize:12}}>{totalSpend>u.budget?'Rozpočet překročen o '+money(totalSpend-u.budget):'Zbývá '+money(u.budget-totalSpend)}</Label></Panel><Section title="Podle kategorií"/><Panel>{Object.keys(cats).length===0?<Label muted>Tento měsíc bez výdajů.</Label>:Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([name,n],i)=><View key={name} style={{marginVertical:13}}><View style={s.between}><Label>{name}</Label><Label style={{fontWeight:'600'}}>{data.hide?'••••':money(n)}</Label></View><View style={[s.track,{backgroundColor:t.soft,marginTop:10}]}><View style={{height:7,borderRadius:8,backgroundColor:['#2EA9F4','#81CFFC','#5A83E8','#A7BDF5'][i%4],width:n/totalSpend*100+'%'}}/></View></View>)}</Panel><Section title="Měnové účty"/><Panel>{Object.entries(u.balances).map(([c,n])=><Row key={c} icon="wallet-outline" title={c} value={data.hide?'••••':money(n,c)} onPress={()=>{setCurrency(c);setTab('Přehled');}}/>)}</Panel></>;};
 const settings=()=> <SettingsHome u={u} data={data} ui={ui3} theme={selectedTheme} onOpen={open} onGo={goV3} onSetting={setting} onLogout={()=>showAuth()}/>;
 const sheetTitles={adminMembership:'Odebrat plán / trial',adminMessages:'Bankovní komunikace',documents:'Dokumenty',homeMode:'Režim zobrazení přehledu',personal:'Osobní údaje',contact:'Kontaktní údaje',address:'Adresa bydliště',taxProfile:'Daňový a ekonomický profil',password:u.auth?'Změna hesla':'Zabezpečit přihlášení',privacy:'Soukromí a oznámení',registrationInfo:'Registrační profil',cardBuilder:'Card Builder',appThemes:'Theme Studio',adminPoints:'Úprava zůstatku bodů',applePay:'Náhled Apple Pay',tierConfirm:'Změna členství',business:'Business na vyžádání',send:review?'Potvrzení platby':'Nová platba',exchange:review?'Potvrzení směny':'Směna měn',request:'Vyžádat platbu',transaction:'Purchase Hub',tiers:'Zenvault Membership',newCard:'Nová karta',cardDesign:'Váš design',limit:'Denní limit',newGoal:'Nový spořicí cíl',goalDeposit:'Odložit peníze',goalWithdraw:'Vybrat z cíle',budget:'Měsíční rozpočet',profile:'Váš profil',accounts:'Vaše účty',newUser:'Nový profil',mode:'Režim aplikace',theme:'Vzhled',adminBalance:'Změnit zůstatek',adminTx:'Vytvořit transakci',notifications:'Oznámení',help:'Centrum nápovědy',about:'Zenvault Bank & Co.',more:'Další možnosti'};
 function sheetBody(){if(!sheet)return null;const type=sheet.type;
  if(['send','exchange','request','goalDeposit','goalWithdraw','adminBalance','adminTx'].includes(type))return <>
   {review?<><Panel><Label muted>{type==='send'?'Příjemce':'Směna'}</Label><Label style={{fontSize:23,fontWeight:'700',marginVertical:13}}>{type==='send'?form.name:review.currency+' → '+review.target}</Label><Label style={{fontSize:28,fontWeight:'700'}}>{money(review.amount,review.currency)}</Label><Label muted style={{marginTop:15}}>{type==='send'?form.account:'Obdržíte '+money(review.received,review.target)}</Label>{form.note&&<Label muted style={{marginTop:12}}>{form.note}</Label>}</Panel><View style={{height:20}}/><Button title={type==='send'?'Potvrdit platbu':'Potvrdit směnu'} onPress={perform}/><Button title="Upravit" secondary onPress={()=>setReview(null)} style={{marginTop:10}}/></>:<>
   {type.startsWith('admin')&&<><Label muted style={{fontSize:12}}>Klient</Label><Chips items={data.users.map(x=>x.name+' · '+x.id.slice(-4))} value={(()=>{const z=data.users.find(x=>x.id===(form.user||u.id));return z.name+' · '+z.id.slice(-4);})()} onChange={v=>f('user',data.users.find(x=>x.name+' · '+x.id.slice(-4)===v).id)}/>{type==='adminTx'&&<Chips items={['Příchozí','Odchozí']} value={form.direction} onChange={v=>f('direction',v)}/>}</>}
   {!type.startsWith('goal')&&<Chips items={['CZK','EUR','USD','GBP']} value={form.currency||currency} onChange={v=>f('currency',v)}/>}
   {sheet.name&&<Label style={{fontWeight:'700',marginVertical:15}}>{sheet.name}</Label>}
   {['send','adminTx'].includes(type)&&<Field label={type==='send'?'Jméno příjemce':'Název transakce'} value={form.name||''} onChangeText={v=>f('name',v)} placeholder="Jméno nebo společnost"/>}
   {type==='send'&&<Field label="Číslo účtu / IBAN" value={form.account||''} onChangeText={v=>f('account',v)} placeholder="123456789/0100" autoCapitalize="characters"/>}
   <Field label={type==='adminBalance'?'Nový zůstatek':'Částka'} value={form.amount||''} onChangeText={v=>f('amount',v)} placeholder="0,00" keyboardType="decimal-pad"/>
   {type==='exchange'&&<><Label muted>Cílová měna</Label><Chips items={['CZK','EUR','USD','GBP']} value={form.target||'EUR'} onChange={v=>f('target',v)}/><Label muted style={{fontSize:12,lineHeight:19,marginVertical:12}}>Referenční kurz: 1 EUR = 25 CZK · 1 USD = 23 CZK · 1 GBP = 29 CZK. Pevný lokální kurz, bez živých tržních dat.</Label></>}
   {['send','request','adminTx'].includes(type)&&<Field label="Poznámka (volitelné)" value={form.note||''} onChangeText={v=>f('note',v)} placeholder="Za co je platba?"/>}
   {['send','adminTx'].includes(type)&&<Chips items={['Převod','Jídlo','Nákupy','Doprava','Předplatné','Příjem','Ostatní']} value={form.category||'Převod'} onChange={v=>f('category',v)}/>}
   {type==='adminTx'&&<><Section title="Kdy bude platba připsána?"/><Chips items={CREDIT_DELAYS.map(x=>x.label)} value={CREDIT_DELAYS.find(x=>x.days===(form.delayDays||0)).label} onChange={label=>setForm(x=>({...x,delayDays:CREDIT_DELAYS.find(d=>d.label===label).days,reason:x.reason||'bank'}))}/>{!!form.delayDays&&<><Label muted style={{lineHeight:21,marginVertical:12}}>Předpokládané připsání: {new Date(creditDate(form.delayDays)).toLocaleString('cs-CZ')}. Jde o kalendářní dny. Do připsání se zůstatek nemění.</Label><Section title="Důvod odložení"/>{PAYMENT_REASONS.map(r=><Pressable key={r.id} accessibilityRole="button" accessibilityLabel={r.label} onPress={()=>f('reason',r.id)} style={{padding:14,marginBottom:8,borderRadius:15,borderWidth:1,borderColor:form.reason===r.id?t.accent:t.border,backgroundColor:t.panel}}><Label style={{fontWeight:'600'}}>{r.label}{form.reason===r.id?' ✓':''}</Label></Pressable>)}<PaymentNote reason={form.reason} dark={dark} dueAt={creditDate(form.delayDays)}/></>}</>}
   <Button style={{marginTop:17}} title={['send','exchange'].includes(type)?'Pokračovat':type==='request'?'Vytvořit a sdílet':'Uložit'} onPress={perform}/>
