import React,{useState,useRef,useEffect,useMemo} from 'react';
import {View,Text,Image,Pressable,Modal,ScrollView,KeyboardAvoidingView,Platform,Animated,Share,Switch} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {LinearGradient} from 'expo-linear-gradient';
import {useReducedMotion} from './Motion';
import {makeId,cents,fmt,isoDay,validDay,CURRENCIES} from './engine';
import {COVERS,validAccount,cleanAccount,parseRequest,requestPayload} from './SmartTransferModel';
import qrcode from './qr';
const modes={instant:'Okamžitě',scheduled:'Naplánovat',recurring:'Opakovat'};
const frequencies={weekly:'Týdně',monthly:'Měsíčně'};
function QR({value}){const q=useMemo(()=>{qrcode.stringToBytes=qrcode.stringToBytesFuncs['UTF-8'];const x=qrcode(0,'M');x.addData(value);x.make();return x;},[value]);const n=q.getModuleCount(),size=208/(n+8);return <View accessibilityLabel="QR žádost Zenvault" style={{alignSelf:'center',backgroundColor:'#FFF',padding:size*4}}>{Array.from({length:n},(_,r)=><View key={r} style={{flexDirection:'row'}}>{Array.from({length:n},(_,c)=><View key={c} style={{width:size,height:size,backgroundColor:q.isDark(r,c)?'#000':'#FFF'}}/>)}</View>)}</View>;}
function Receipt({value,ui,onClose,onShare}){const {Label,Button,t,Row}=ui,reduced=useReducedMotion(),anim=useRef(new Animated.Value(0)).current;useEffect(()=>{if(reduced){anim.setValue(1);return;}const a=Animated.spring(anim,{toValue:1,damping:19,stiffness:135,mass:1,useNativeDriver:true});a.start();return()=>a.stop();},[reduced]);const cover=COVERS.find(x=>x.id===value.cover)||COVERS[0];return <Animated.View testID="smart-receipt" style={{opacity:anim,transform:[{translateY:anim.interpolate({inputRange:[0,1],outputRange:[35,0]})},{scale:anim.interpolate({inputRange:[0,1],outputRange:[.94,1]})}]}}><LinearGradient colors={cover.colors} style={{borderRadius:28,padding:28,alignItems:'center'}}>{!!value.coverUrl&&<Image source={{uri:value.coverUrl}} style={{position:'absolute',top:0,left:0,right:0,bottom:0,opacity:.25,borderRadius:28}}/>}<Text style={{fontSize:46}}>{value.emoji||'↗'}</Text><Text style={{color:'#FFF',fontSize:12,letterSpacing:2,marginTop:16}}>ZENVAULT® · SMART TRANSFER</Text><Text style={{color:'#FFF',fontSize:30,fontWeight:'800',marginTop:18}}>{fmt(value.amount,value.currency)}</Text><Text style={{color:'#FFF',fontSize:17,marginTop:10,textAlign:'center'}}>{value.name}</Text><View style={{marginTop:22,borderRadius:22,backgroundColor:'#FFFFFF28',padding:12}}><Text style={{color:'#FFF',fontWeight:'700'}}>✓ {value.title}</Text></View></LinearGradient><View style={{borderRadius:24,backgroundColor:t.panel,padding:20,marginTop:12}}><Row title="Datum" value={new Date(value.date).toLocaleString('cs-CZ')}/>{value.next&&<Row title="První provedení" value={value.next}/>}<Label muted style={{fontSize:12,marginTop:10}}>Reference: {value.id}</Label>{!!value.note&&<Label style={{marginTop:15,lineHeight:23}}>{value.note}</Label>}<Label muted style={{fontSize:12,lineHeight:19,marginTop:15}}>{value.scope}</Label></View><Button title="Sdílet potvrzení" secondary onPress={onShare} style={{marginTop:18}}/><Button title="Hotovo" onPress={onClose} style={{marginTop:10}}/></Animated.View>;}
export default function SmartTransfer({u,data,ui,dispatch,onBack,initial='transfer'}){
 const {t,Panel,Label,Button,Row,Field,Chips,Section,Icon}=ui,insets=useSafeAreaInsets(),reduced=useReducedMotion();const [flow,F]=useState(null),[step,S]=useState(0),[form,V]=useState({}),[error,E]=useState(''),[query,Q]=useState(''),[receipt,R]=useState(null),[detail,D]=useState(null);const op=useRef(makeId()),busy=useRef(false);const set=(k,v)=>V(f=>({...f,[k]:v}));
 const start=(kind,seed={})=>{op.current=makeId();busy.current=false;F(kind);S(0);E('');R(null);D(null);V({currency:'CZK',mode:'instant',next:isoDay(),frequency:'monthly',cover:'sky',emoji:'↗',...seed});};
 const close=()=>{F(null);E('');};
 const share=async message=>{try{await Share.share({message});}catch{E('Sdílení se nepodařilo otevřít.');}};
 const field=(k,label,opts={})=><Field label={label} value={String(form[k]||'')} onChangeText={v=>{set(k,v);E('');}} {...opts}/>;
 const currency=<Chips items={CURRENCIES} value={form.currency} onChange={v=>set('currency',v)}/>;
 const look=<><Section title="Dej převodu svůj styl"/><Chips items={COVERS.map(x=>x.name)} value={COVERS.find(x=>x.id===form.cover)?.name} onChange={v=>set('cover',COVERS.find(x=>x.name===v).id)}/><Chips items={['↗','❤️','🎁','🍕','☕','🏠','✨']} value={form.emoji} onChange={v=>set('emoji',v)}/>{field('emoji','Vlastní emoji',{maxLength:12})}{field('coverUrl','Vlastní cover – HTTPS odkaz na obrázek',{autoCapitalize:'none',maxLength:1200,placeholder:'https://…'})}{field('note','Zpráva k platbě',{maxLength:240,multiline:true})}</>;
 function validate(){const n=cents(form.amount);if(form.coverUrl&&!/^https:\/\//i.test(form.coverUrl))throw Error('Obrázek musí mít HTTPS adresu.');if(!Number.isSafeInteger(n)||n<=0)throw Error('Zadej kladnou částku na nejvýše dvě desetinná místa.');if(flow==='transfer'){if(!form.name?.trim())throw Error('Vyplň příjemce.');if(!form.target&&!validAccount(form.account))throw Error('Zkontroluj číslo účtu / IBAN.');if(form.mode!=='instant'&&(!validDay(form.next)||form.next<isoDay()))throw Error('Vyber dnešní nebo budoucí datum RRRR-MM-DD.');}if(flow==='request'&&form.iban&&!validAccount(form.iban))throw Error('Zkontroluj účet / IBAN.');if(flow==='split'){const ps=(form.people||'').split(',').map(x=>x.trim()).filter(Boolean);if(ps.length<2||ps.length>20||n<ps.length)throw Error('Zadej 2–20 účastníků a alespoň haléř pro každého.');}return n;}
 const review=()=>{try{validate();E('');S(2);}catch(e){E(e.message);}};
 function confirm(){if(busy.current)return;try{const amount=validate();busy.current=true;const value={...form,amount,account:cleanAccount(form.account)},scheduled=flow==='transfer'&&form.mode!=='instant';const action=scheduled?{type:'plan',id:form.planId,kind:'transfer',name:form.name,data:value,next:form.next,frequency:form.mode==='scheduled'?'once':form.frequency}:{type:flow,...value};const ok=dispatch({...action,op:op.current,silent:true,smartReceipt:true});if(!ok){E('Operaci se nepodařilo dokončit. Zkontroluj zůstatek a údaje příjemce.');busy.current=false;return;}R({...value,next:scheduled?form.next:null,id:op.current,date:new Date().toISOString(),title:scheduled?'Příkaz uložen':flow==='request'?'Žádost připravena':flow==='split'?'Účet rozdělen':'Platba dokončena',scope:scheduled?'Peníze zatím nebyly odečteny. Příkaz se provede při otevření nebo návratu do aplikace.':flow==='transfer'?(form.target?'Zaúčtováno mezi místními účty Zenvault.':'Zaúčtováno v místní evidenci. Externí bankovní převod nebyl odeslán.'):'Uloženo v Zenvaultu. Zůstatek se nemění.'});}catch(e){busy.current=false;E(e.message);}}
 const local=data.users.filter(x=>x.id!==u.id&&!x.parentId),contacts=[...local.map(x=>({id:x.id,target:x.id,name:x.name,account:'',sub:x.auth?.phone||'Místní účet Zenvault'})),...u.contacts.filter(c=>!c.target||!local.some(x=>x.id===c.target))].filter(c=>(c.name+' '+c.account+' '+(c.sub||'')).toLowerCase().includes(query.toLowerCase()));
 useEffect(()=>{if(initial==='requests')start('request');},[]);
 const pending=u.plans.filter(p=>p.kind==='transfer');
 let body;
 if(receipt)body=<Receipt value={receipt} ui={ui} onClose={close} onShare={()=>share(`Zenvault · ${receipt.title}\n${fmt(receipt.amount,receipt.currency)}\n${receipt.name||''}\n${receipt.note||''}\n${receipt.scope}\nReference: ${receipt.id}`)}/>;
 else if(detail)body=<><QR value={requestPayload(detail,u.name)}/><Label style={{fontSize:30,fontWeight:'800',textAlign:'center',marginVertical:20}}>{fmt(detail.amount,detail.currency)}</Label><Label muted style={{lineHeight:21,marginBottom:18}}>QR žádost Zenvault. Obsah QR lze vložit v Smart Transfer → QR platba. Není to bankovní platební QR.</Label><Button title="Sdílet QR obsah" onPress={()=>share(requestPayload(detail,u.name))}/></>;
 else if(flow==='qr')body=<><Label muted style={{lineHeight:22,marginBottom:18}}>Vlož text z QR žádosti Zenvault nebo sdílený obsah žádosti. Před odesláním vždy zkontroluješ příjemce a částku.</Label>{field('payload','Obsah QR žádosti',{multiline:true})}<Button title="Načíst žádost" onPress={()=>{try{const p=parseRequest(form.payload);if(p.target===u.id)throw Error('Vlastní žádost nemůžeš zaplatit.');start('transfer',p);S(1);}catch(e){E(e.message);}}}/></>;
 else if(step===2)body=<><LinearGradient colors={(COVERS.find(x=>x.id===form.cover)||COVERS[0]).colors} style={{padding:25,borderRadius:25,marginBottom:20}}>{!!form.coverUrl&&<Image source={{uri:form.coverUrl}} style={{position:'absolute',top:0,left:0,right:0,bottom:0,opacity:.25,borderRadius:25}}/>}<Text style={{fontSize:38}}>{form.emoji}</Text><Text style={{fontSize:30,fontWeight:'800',color:'#FFF',marginTop:15}}>{fmt(cents(form.amount),form.currency)}</Text><Text style={{color:'#FFF',fontSize:18,marginTop:12}}>{form.name|| (flow==='request'?'Žádost o peníze':'Společný účet')}</Text></LinearGradient><Panel>{flow==='transfer'&&<><Row title="Příjemce" value={form.name}/><Row title="Kam" value={form.target?'Místní účet Zenvault':cleanAccount(form.account)}/><Row title="Provedení" value={modes[form.mode]}/>{form.mode!=='instant'&&<Row title="Datum" value={form.next}/>}</>}{flow==='split'&&<Label>{form.people}</Label>}{!!form.note&&<Label style={{lineHeight:22,marginTop:14}}>{form.note}</Label>}<Label muted style={{fontSize:12,lineHeight:20,marginTop:14}}>{flow==='transfer'?(form.mode!=='instant'?'Příkaz proběhne při otevření aplikace. Nedostatek prostředků se zobrazí v jeho stavu.':form.target?'Částka se ihned přesune mezi místními účty.':'Převod se zapíše do místní evidence, neodesílá se do externí banky.'):'Vytvoření žádosti nebo rozpisu neodečte peníze.'}</Label></Panel><Button title={flow==='transfer'?(form.mode==='instant'?'Odeslat platbu':'Uložit příkaz'):flow==='request'?'Vytvořit žádost':'Rozdělit účet'} onPress={confirm} style={{marginTop:20}}/><Button title="Upravit údaje" secondary onPress={()=>S(1)} style={{marginTop:10}}/></>;
 else if(flow==='transfer'&&step===0)body=<><Field label="Najít kontakt" value={query} onChangeText={Q} placeholder="Jméno, telefon nebo účet"/><Panel>{contacts.slice(0,12).map(c=><Row key={c.id} icon="person-circle-outline" title={c.name} sub={c.sub||c.account} onPress={()=>{V(f=>({...f,name:c.name,account:c.account,target:c.target||null}));S(1);}}/>)}{!contacts.length&&<Label muted>Žádný kontakt. Zadej příjemce níže.</Label>}</Panel><Section title="Nový příjemce"/>{field('name','Jméno příjemce')}{field('account','Účet / IBAN',{autoCapitalize:'characters'})}<Button title="Pokračovat k částce" onPress={()=>{if(!form.name?.trim()||!validAccount(form.account)){E('Vyplň jméno a platný účet / IBAN.');return;}set('target',null);S(1);E('');}}/></>;
 else body=<>{flow==='transfer'&&<><Row icon="person-circle-outline" title={form.name} sub={form.target?'Místní účet Zenvault':form.account}/><Button title="Změnit příjemce" secondary onPress={()=>S(0)} style={{marginBottom:18}}/></>}{flow==='split'&&field('name','Název společného účtu')}{currency}{field('amount',flow==='split'?'Celkem':'Částka',{keyboardType:'decimal-pad'})}{flow==='split'&&field('people','Účastníci oddělení čárkou',{placeholder:'Já, Alex, Robin'})}{flow==='request'&&field('iban','Účet / IBAN (volitelné)')}{flow==='transfer'&&<><Section title="Kdy peníze odejdou"/><Chips items={Object.values(modes)} value={modes[form.mode]} onChange={v=>set('mode',Object.keys(modes).find(k=>modes[k]===v))}/>{form.mode!=='instant'&&field('next','Datum (RRRR-MM-DD)',{placeholder:isoDay()})}{form.mode==='recurring'&&<Chips items={Object.values(frequencies)} value={frequencies[form.frequency]} onChange={v=>set('frequency',Object.keys(frequencies).find(k=>frequencies[k]===v))}/>}</>}{look}<Button title="Zkontrolovat" onPress={review}/></>;
 return <><Button title="Zpět na přehled" secondary onPress={onBack}/><Label muted style={{letterSpacing:2,fontSize:11,marginTop:28}}>MONEY, WITH A PERSONAL TOUCH.</Label><Label style={{fontSize:36,fontWeight:'800',letterSpacing:-1.5,marginVertical:12}}>Smart Transfer 5</Label><Label muted style={{lineHeight:23,marginBottom:24}}>Každá platba má svůj příběh.</Label><LinearGradient colors={['#132948','#2162A3']} style={{padding:24,borderRadius:28,marginBottom:20}}><Text style={{color:'#AECDEE',fontSize:12}}>POŠLI. NAPLÁNUJ. POTĚŠ.</Text><Text style={{color:'#FFF',fontSize:25,fontWeight:'700',marginTop:10,marginBottom:24}}>Peníze na správném místě.</Text><Button title="Poslat peníze" icon="arrow-up-outline" onPress={()=>start('transfer')}/></LinearGradient><View style={{flexDirection:'row',gap:8,flexWrap:'wrap'}}>{[['request','Vyžádat peníze'],['split','Rozdělit účet'],['qr','QR platba']].map(([key,title])=><Button key={key} title={title} secondary onPress={()=>start(key)}/>)}</View><Section title="Příkazy a opakování"/>{!pending.length&&<Panel><Label muted>Naplánuj první převod. Tady najdeš jeho stav i úpravy.</Label></Panel>}{pending.map(p=><Panel key={p.id} style={{marginBottom:12}}><Row icon="calendar-outline" title={p.name} sub={`${p.next} · ${p.frequency==='once'?'Jednorázově':frequencies[p.frequency]} · ${{scheduled:'Naplánováno',paid:p.active?'Další termín připraven':'Provedeno',failed:'Neprovedeno',cancelled:'Zrušeno'}[p.status]}`}/><Label>{fmt(p.data.amount,p.data.currency)}</Label>{p.error&&<Label style={{color:t.accent,marginTop:10}}>{p.error}</Label>}{p.active&&<View style={{gap:8,marginTop:14}}><Button title={'Upravit '+p.name} secondary onPress={()=>{start('transfer',{...p.data,amount:String(p.data.amount/100),planId:p.id,next:p.next,mode:p.frequency==='once'?'scheduled':'recurring',frequency:p.frequency});S(1);}}/><Button title={'Zrušit '+p.name} secondary onPress={()=>dispatch({type:'planCancel',id:p.id,op:makeId()})}/></View>}</Panel>)}<Section title="Žádosti o peníze"/>{u.requests.map(r=><Panel key={r.id} style={{marginBottom:10}}><Row icon="qr-code-outline" title={fmt(r.amount,r.currency)} sub={(r.status==='paid'?'Zaplaceno · ':'')+(r.note||'Žádost o platbu')} onPress={()=>{F('request');R(null);D({...r,ownerId:r.ownerId||u.id});E('');}}/></Panel>)}{!u.requests.length&&<Label muted>Zatím žádné žádosti.</Label>}<Section title="Rozdělené účty"/>{u.splits.map(sp=><Panel key={sp.id} style={{marginBottom:12}}><Label style={{fontSize:20,fontWeight:'700'}}>{sp.emoji||'🍕'} {sp.name}</Label>{sp.parts.map(p=><Row key={p.id} title={p.name} sub={fmt(p.amount,sp.currency)} right={<Switch accessibilityLabel={'Uhrazeno '+p.name} value={p.paid} onValueChange={()=>dispatch({type:'splitPaid',id:sp.id,part:p.id,op:makeId()})}/>}/>)}<Button title="Sdílet rozpis" secondary onPress={()=>share(sp.name+'\n'+sp.parts.map(p=>p.name+': '+fmt(p.amount,sp.currency)).join('\n'))}/>{sp.parts.map(part=><Button key={part.id} title={'Vyžádat podíl · '+part.name} secondary style={{marginTop:8}} onPress={()=>start('request',{amount:String(part.amount/100),currency:sp.currency,note:sp.name+' · '+part.name,emoji:sp.emoji,cover:sp.cover})}/>)}<Label muted style={{fontSize:12,marginTop:12}}>Ruční evidence úhrad. Označení nemění zůstatek.</Label></Panel>)}<Modal visible={!!flow} transparent animationType={reduced?'none':'slide'} onRequestClose={close}><View style={{flex:1,backgroundColor:'#08172A88',justifyContent:'flex-end'}}><KeyboardAvoidingView behavior={Platform.OS==='ios'?'padding':undefined} style={{maxHeight:'93%',width:'100%',maxWidth:560,alignSelf:'center'}}><View style={{backgroundColor:t.bg,borderTopLeftRadius:30,borderTopRightRadius:30,flexShrink:1}}><View style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between',padding:22}}><Label style={{fontSize:22,fontWeight:'800'}}>{receipt?'Hotovo. S lehkostí.':detail?'Žádost o peníze':flow==='transfer'?'Smart Transfer 5':flow==='qr'?'QR platba':flow==='split'?'Split payment':'