SmartTransferModel.js.contents:
// Portable local payment payloads. These are Zenvault requests, not bank-network orders.
export const COVERS=[{id:'sky',name:'Sky',colors:['#147DF5','#5DBBFF']},{id:'midnight',name:'Midnight',colors:['#172039','#45527B']},{id:'rose',name:'Rose',colors:['#AF277A','#ED81B9']},{id:'mint',name:'Mint',colors:['#08786E','#38BBA0']}];
export const cleanAccount=s=>String(s||'').replace(/\s/g,'').toUpperCase();
export function validAccount(value){const s=cleanAccount(value);if(/^(\d{1,6}-)?\d{2,10}\/\d{4}$/.test(s))return true;if(!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(s))return false;const sizes={CZ:24,SK:24,DE:22,AT:20,GB:22,FR:27,ES:24,IT:27,PL:28,NL:18,BE:16,CH:21};if(sizes[s.slice(0,2)]&&s.length!==sizes[s.slice(0,2)])return false;let r=0;for(const c of s.slice(4)+s.slice(0,4)){for(const n of /[A-Z]/.test(c)?String(c.charCodeAt(0)-55):c)r=(r*10+Number(n))%97;}return r===1;}
export const appearance=a=>({emoji:String(a.emoji||'↗').slice(0,12),cover:COVERS.some(x=>x.id===a.cover)?a.cover:'sky',note:String(a.note||'').trim().slice(0,240),coverUrl:/^https:\/\//i.test(a.coverUrl||'')?String(a.coverUrl).slice(0,1200):''});
export function requestPayload(r,name){return JSON.stringify({app:'zenvault',v:1,id:r.id,name:String(name).slice(0,80),target:r.ownerId,account:r.iban||'',amount:r.amount,currency:r.currency,note:r.note||'',emoji:r.emoji||'↗',cover:r.cover||'sky'});}
export function parseRequest(text){let r;try{r=JSON.parse(text);}catch{throw Error('Vlož obsah QR žádosti Zenvault.');}if(r.app!=='zenvault'||r.v!==1||!r.id||!Number.isSafeInteger(r.amount)||r.amount<=0||!['CZK','EUR','USD','GBP'].includes(r.currency)||!r.name)throw Error('Neplatná QR žádost.');if(!r.target&&!validAccount(r.account))throw Error('Žádost nemá platného příjemce.');return {name:String(r.name).slice(0,80),target:r.target,account:cleanAccount(r.account),amount:String(r.amount/100),currency:r.currency,requestId:r.id,...appearance(r)};}

