const modules=[['intelligence5','sparkles-outline','Zenvault Intelligence','Forecast, změny a finanční souvislosti'],['cards5','card-outline','Card Center 5','Karty, Travel Mode a subscriptions'],['sharedVaults5','people-outline','Shared Vaults','Společné Spaces a členové'],['subscriptions5','repeat-outline','Subscriptions Hub 5','Předplatná, termíny a karty'],['purchase5','receipt-outline','Purchase Hub','Nákupy, merchant detail a receipts'],['moments5','flash-outline','Zenvault Moments','Milníky, security a rewards'],['security5','shield-checkmark-outline','Security Center 5','Identity, relace a emergency'],['plans5','diamond-outline','Plan Center 5','Membership, rewards a kolekce'],['admin5','construct-outline','Admin Studio 5','Klientské nástroje nové generace'],['prestigeLounge','diamond-outline','Prestige Circle','Prestige a Prestige MAX · nad Business'],['prestigeMax','sparkles-outline','Prestige MAX Atelier','Nejvyšší úroveň · exkluzivní kolekce'],['prestige','flame-outline','Prestige Atelier','Crimson Collection · Card Builder'],['unlimitedMax','sparkles-outline','Unlimited MAX','Unlimited MAX · MAX Atelier'],['unlimited','infinite-outline','Unlimited ∞','Card Builder a vyšší úroveň členství'],['investments','trending-up-outline','Investments','Vlastní evidence portfolia'],['insights','analytics-outline','Insights','Porovnej měsíce a kategorie'],['vaults','sparkles-outline','Vaults / Spaces','Peníze s vlastním plánem'],['cardpay','card-outline','Platba kartou','Lokální operace a kontrola karty'],['controls','options-outline','Card Controls','Limity, země a jednorázové karty'],['rewards','gift-outline','Rewards & Points','Odměny, nabídky a odemknutí'],['subscriptions','repeat-outline','Předplatná','Ceny, další platby a blokace'],['transfer','swap-horizontal-outline','Smart Transfer','Příjemci, plánování a split bill'],['requests','qr-code-outline','Payment Requests','Sdílej částku a QR žádost'],['wallet','wallet-outline','Multi-currency Wallet','Čtyři měny v