export function PaymentMoment({moment,onClose,ui}){const {t,Label,Icon}=ui;const a=useRef(new Animated.Value(0)).current;useEffect(()=>{if(!moment)return;let stopped=false;AccessibilityInfo.isReduceMotionEnabled().then(reduced=>{if(stopped)return;if(reduced)a.setValue(1);else Animated.timing(a,{toValue:1,duration:260,useNativeDriver:true}).start();});const id=setTimeout(onClose,2300);return()=>{stopped=true;clearTimeout(id);a.setValue(0);};},[moment]);if(!moment)return null;return <Modal visible transparent animationType="none" onRequestClose={onClose}><Pressable accessibilityRole="button" accessibilityLabel="Zavřít potvrzení platby" onPress={onClose} style={{flex:1,backgroundColor:'#071B34CC',alignItems:'center',justifyContent:moment.large?'center':'flex-start',paddingTop:90,paddingHorizontal:24}}><Animated.View style={{opacity:a,transform:[{scale:a.interpolate({inputRange:[0,1],outputRange:[.94,1]})}],backgroundColor:t.panel,padding:30,borderRadius:30,width:'100%',maxWidth:440,alignItems:'center'}}><Icon name={moment.large?'sparkles':'checkmark-circle'} color={t.accent} size={60}/><Label style={{fontSize:24,fontWeight:'800',marginTop:15,textAlign:'center'}}>{moment.title||'Payment completed'}</Label><Label muted style={{marginTop:12,fontSize:17}}>{moment.amount?fmt(moment.amount,moment.currency||'CZK'):'Hotovo'}</Label></Animated.View></Pressable></Modal>;}
