export default function V3Page({section,u,data,ui,dispatch,go,onOpen,onSheet,renderCard,tiers,onLock,notice,feedback,onTransaction}){
 const reduced=useReducedMotion();const {t,Panel,Label,Button,Icon,Section,Field,Chips,Row}=ui;const insets=useSafeAreaInsets();const [modal,M]=useState(null),[form,F]=useState({}),[review,R]=useState(false),[answer,A]=useState(''),[query,Q]=useState(''),[galleryTier,GT]=useState(u.tier),[kind,K]=useState('Virtuální'),[processing,P]=useState(false);const operation=useRef(makeId());
