 if(section==='prestigeLounge')content=<PrestigeCenter u={u} ui={ui} go={go} onOpen={onOpen} dispatch={dispatch}/>;
 if(section==='unlimited'||section==='unlimitedMax'||section==='maxArt'||section==='prestige'||section==='prestigeMax')content=<UnlimitedStudio key={section} initialCollection={section==='maxArt'?'art':undefined} plan={section==='prestige'?PRESTIGE_TIER:section==='prestigeMax'?PRESTIGE_MAX_TIER:section==='unlimited'?'Unlimited':MAX_TIER} u={u} ui={ui} dispatch={dispatch} renderCard={renderCard} onSaved={()=>onOpen('Karty')} onMembership={tier=>onOpen(tier===PRESTIGE_TIER?'prestigePlan':tier===PRESTIGE_MAX_TIER?'prestigeMaxPlan':tier===MAX_TIER?'unlimitedMaxPlan':'unlimitedPlan')}/>;
 if(section==='hub')content=<><LinearGradient colors={t.featureGradient} start={{x:0,y:0}} end={{x:1,y:1}} style={{padding:25,borderRadius:28,marginBottom:24,overflow:'hidden'}}><View style={{position:'absolute',right:-35,top:-35,width:150,height:150,borderRadius:75,borderWidth:28,borderColor:'#FFFFFF20'}}/><Icon name="planet-outline" color={t.accent} size={35}/><Label style={{fontSize:30,fontWeight:'700',letterSpacing:-1,marginTop:18}}>Více než účet.</Label><Label muted style={{lineHeight:22,fontSize:14,marginTop:9}}>Malé radosti. Velké plány. Objev všechno, co tvůj Zenvault umí.</Label></LinearGradient><View style={{flexDirection:'row',flexWrap:'wrap',justifyContent:'space-between',gap:12}}>{modules.filter(m=>!u.parentId||!['junior','private','business'].includes(m[0])).map(m=><Touch accessibilityRole="button" accessibilityLabel={m[2]} key={m[0]} onPress={()=>go(m[0])} style={{width:'48%',backgroundColor:t.glass?t.surface:t.panel,borderWidth:1,borderColor:t.border,borderRadius:25,padding:18,minHeight:162}}><View style={{flexDirection:'row',justifyContent:'space-between',alignItems:'center'}}><View style={{width:40,height:40,borderRadius:15,backgroundColor:t.soft,alignItems:'center',justifyContent:'center'}}><Icon name={m[1]} color={t.accent} size={21}/></View><Icon name="arrow-forward" color={t.muted} size={14}/></View><Label style={{fontWeight:'700',fontSize:15,letterSpacing:-.3,marginTop:14}}>{m[2]}</Label><Label muted style={{fontSize:11,lineHeight:17,marginTop:6}}>{m[3]}</Label></Touch>)}</View></>;

 if(section==='insights'){const now=monthStats(u),prev=monthStats(u,-1);const diff=prev.expense?Math.round((now.expense/prev.expense-1)*100):null;content=<>{stat('Tento měsíc',fmt(now.expense),diff===null?'Minulý měsíc nemá výdaje pro srovnání.':`${Math.abs(diff)} % ${diff>=0?'více':'méně'} než minulý měsíc.`)}<Panel><Row title="Minulý měsíc" value={fmt(prev.expense)}/><Row title="Příjmy tento měsíc" value={fmt(now.income)}/><Row title="Měsíční rozpočet" value={fmt(u.budget)}/></Panel><Section title="Kategorie a souvislosti"/>{Object.entries(now.categories).map(([name,n])=><Panel key={name} style={{marginBottom:12}}><Row title={name} value={fmt(n)}/><View style={{height:7,backgroundColor:t.soft,borderRadius:10,overflow:'hidden'}}><View style={{height:7,backgroundColor:t.accent,width:(n/Math.max(now.expense,1)*100)+'%'}}/></View><Label muted style={{fontSize:12,lineHeight:20,marginTop:12}}>{prev.categories[name]?`${Math.abs(Math.round((n/prev.categories[name]-1)*100))} % ${n>=prev.categories[name]?'více':'méně'} než minulý měsíc.`:'Nové výdaje bez základu pro srovnání.'}</Label></Panel>)}{!now.expense&&empty('Zatím bez výdajů v tomto měsíci.')}<Label muted style={{fontSize:12,lineHeight:20,marginTop:15}}>Částky přepočítáváme referenčními kurzy. Přesuny mezi vlastními kapsami, směny a úpravy zůstatku nejsou spotřeba.</Label></>;}
 if(section==='vaults')content=<>{stat('Ve tvých Vaults',fmt(u.goals.reduce((n,g)=>n+g.saved,0)))}<Button title="Nový Vault" icon="add" onPress={()=>open('vaultSave',{name:'Travel',target:'10000',icon:'airplane-outline',color:'#209ACB'})}/><Chips items={['Travel','Emergency','Car','Festival','Business']} value="" onChange={v=>open('vaultSave',{name:v,target:'10000',icon:{Travel:'airplane-outline',Emergency:'shield-outline',Car:'car-outline',Festival:'musical-notes-outline',Business:'briefcase-outline'}[v]})}/>{u.goals.map(g=><Panel key={g.id} style={{marginTop:14}}><Row icon={g.icon||'sparkles-outline'} title={g.name} value={Math.round(g.saved/g.target*100)+' %'} onPress={()=>open('vaultSave',{...g,target:String(g.target/100)})}/><View style={{height:7,backgroundColor:t.soft,borderRadius:6,overflow:'hidden'}}><View style={{height:7,width:Math.min(100,g.saved/g.target*100)+'%',backgroundColor:g.color||t.accent}}/></View><Label muted style={{marginVertical:13}}>{fmt(g.saved)} z {fmt(g.target)}</Label><View style={{flexDirection:'row',gap:8}}><Button style={{flex:1}} title="Odložit" onPress={()=>open('vaultMove',{id:g.id,withdraw:false})}/><Button style={{flex:1}} title="Vybrat" secondary onPress={()=>open('vaultMove',{id:g.id,withdraw:true})}/></View><Button title="Automatické spoření" secondary style={{marginTop:9}} onPress={()=>open('autoVault',{id:g.id,name:g.name,next:isoDay(),frequency:'monthly'})}/></Panel>)}<Section title="Automatické příkazy"/>{planList('vault')}</>;
 if(section==='wallet')content=<><Label muted style={{lineHeight:22,marginBottom:16}}>Samostatné zůstatky. Pevné referenční kurzy bez poplatku za směnu.</Label>{CURRENCIES.map(c=><Panel key={c} style={{marginBottom:12}}><Row icon="wallet-outline" title={c} value={data.hide?'••••':fmt(u.balances[c],c)} onPress={()=>open('exchange',{from:c,to:c==='EUR'?'CZK':'EUR'})}/></Panel>)}<Button title="Směnit" onPress={()=>open('exchange',{from:'CZK',to:'GBP'})}/><Section title="Referenční kurzy"/><Panel>{CURRENCIES.filter(c=>c!=='CZK').map(c=><Row key={c} title={'1 '+c} value={RATES[c]+' CZK'}/>)}</Panel></>;
 if(section==='cardpay')content=<><Panel><Icon name="card-outline" color={t.accent} size={40}/><Label style={{fontWeight:'800',fontSize:24,marginVertical:15}}>Všechno začíná platbou.</Label><Label muted style={{lineHeight:23}}>Tato lokální karetní operace propojí limity, země, blokace, odměny a historii. Neodesílá peníze do karetní sítě.</Label><Button style={{marginTop:20}} title="Nová karetní platba" onPress={()=>open('cardPay',{card:u.cards[0]?.id,currency:'CZK',channel:'online',country:'CZ',merchant:PARTNERS[0].name})}/></Panel><Section title="Šablony obchodníků"/><Label muted style={{fontSize:12,lineHeight:20}}>Vyber značku, doplň částku a potvrď platbu.</Label><MerchantTemplates t={t} onSelect={m=>open('cardPay',{card:u.cards[0]?.id,currency:'CZK',country:'CZ',merchant:m.name,merchantId:m.id,category:m.category,channel:m.channel})}/><Section title="Vybraní obchodníci"/><Panel>{PARTNERS.map(p=><Row key={p.id} icon={p.icon} title={p.name} sub={'Cashback '+(100*(CASHBACK[u.tier]||0))+' %'} onPress={()=>open('cardPay',{card:u.cards[0]?.id,currency:'CZK',channel:'online',country:'CZ',merchant:p.name})}/>)}</Panel><Section title="Poslední karetní platby"/><Panel>{u.transactions.filter(x=>x.kind==='card').slice(0,8).map(x=><Row key={x.id} leading={merchantForTransaction(x)?<MerchantIcon merchant={merchantForTransaction(x)}/>:null} icon="card-outline" title={x.name} sub={x.category+' · '+new Date(x.date).toLocaleDateString('cs-CZ')} value={data.hide?'••••':fmt(x.value,x.currency)} onPress={()=>onTransaction(x)}/>)}{!u.transactions.some(x=>x.kind==='card')&&<Label muted>Po první platbě se tady objeví obchodník i jeho logo.</Label>}</Panel></>;
 if(section==='controls')content=<><Button title="Jednorázová virtuální karta" icon="refresh-outline" secondary onPress={()=>action('disposable')}/><Label muted style={{fontSize:12,lineHeight:20,marginVertical:14}}>Pro / Ultra / Ultra MAX / Unlimited ∞ / Unlimited MAX. Po úspěšné online platbě se v lokálním profilu obnoví identifikátor a poslední čtyřčíslí.</Label>{u.cards.map(c=><Panel key={c.id} style={{marginBottom:15}}>{renderCard(c)}<Label muted style={{marginTop:12,fontSize:12}}>{c.owner||c.type}{c.disposable?' · Disposable · verze '+c.credentialVersion:''}</Label>{[['frozen','Zmrazená'],['online','Online platby'],['atm','Výběry ATM'],['foreign','Zahraniční platby'],['contactless','Bezkontaktní platby']].map(([k,label])=><Row key={k} title={label} right={<Switch accessibilityLabel={label+' '+c.last} value={!!c[k]} onValueChange={v=>action('controls',{id:c.id,values:{[k]:v}})} trackColor={{true:t.button}}/>}/>)}<Row title="Denní limit" value={fmt(c.limit)} onPress={()=>open('cardLimit',{id:c.id,limit:String(c.limit/100)})}/><Row title="Povolené země" sub={c.countries?.length?c.countries.join(', '):'Všechny země v nabídce'} onPress={()=>open('countries',{id:c.id,countries:c.countries||[]})}/></Panel>)}</>;
 if(section==='rewards')content=<>{stat('Zenvault Points',u.points+' bodů',pointsRateLabel(u)+' za každých celých 100 Kč ekvivalentu úspěšného nákupu kartou. ATM, vlastní převody a admin úpravy body negenerují.')}{stat('Připsaný cashback',fmt(u.cashbackTotal),'U vybraných obchodníků: '+(100*(CASHBACK[u.tier]||0))+' %'+(u.boost?' · aktivní boost +0,5 %':''))}<Section title="Offers"/><Panel>{PARTNERS.map(p=><Row key={p.id} icon={p.icon} title={p.name} sub={p.category+' · '+(100*(CASHBACK[u.tier]||0))+' % cashback'} onPress={()=>go('cardpay')}/>)}</Panel><Label muted style={{fontSize:12,lineHeight:19,marginTop:10}}>Katalog pro lokální karetní operace; nejde o potvrzené nabídky externích partnerů.</Label><Section title="Odměň se"/>{REWARDS.map(r=><Panel key={r.id} style={{marginBottom:12}}><Row title={r.name} value={rewardCost(u,r)===0?(isPrestigeTier(u.tier)?'V CENĚ '+u.tier:isMax(u)?'V CENĚ MAX':'ZDARMA S BUSINESS'):r.cost+' bodů'}/>{r.id==='design'&&includedReward(u,'design')?<Button title="Vybrat Hologram Limited zdarma" secondary onPress={()=>go('gallery')}/>:r.id==='theme'&&hasMaxBenefits(u)?<Button title={isPrestigeTier(u.tier)?'Použít Candy Sky v ceně '+u.tier:'Použít Candy Sky v ceně MAX'} secondary onPress={()=>action('appTheme',{id:'candy'})}/>:u.unlocks.includes(r.id)?<><Label style={{color:t.accent,fontWeight:'700'}}>Odemčeno ✓</Label>{(r.id==='rollingLoud'||r.id==='design')&&<Button style={{marginTop:10}} title="Otevřít Card Gallery" secondary onPress={()=>go('gallery')}/>}</>:<Button title={'Získat: '+r.name} secondary onPress={()=>open('redeem',{id:r.id})}/>}</Panel>)}{u.unlocks.includes('theme')&&<Button title={u.rewardTheme?'Vrátit motiv tarifu':'Použít Candy Sky'} onPress={()=>action('rewardTheme',{enabled:!u.rewardTheme})}/>}{u.unlocks.includes('subscription')&&<Panel style={{marginTop:14}}><Label muted>Poukaz je uložený mezi tvými odměnami. Partnerský aktivační kód zatím není dostupný.</Label></Panel>}<Section title="Pohyb bodů"/><Panel>{u.pointsLog.slice(0,20).map(x=><Row key={x.id} title={x.name} sub={x.admin?(x.before+' → '+x.after+' bodů'+(x.note?' · '+x.note:'')):undefined} value={(x.value>0?'+':'')+x.value+' bodů'}/>)}{!u.pointsLog.length&&<Label muted>Zatím bez pohybu bodů.</Label>}</Panel></>;
 if(section==='subscriptions')content=<><Button title="Přidat předplatné" icon="add" onPress={()=>open('subscription',{name:'Netflix',currency:'CZK',next:isoDay(),card:u.cards[0]?.id,frequency:'monthly',auto:false})}/><Chips items={['Netflix','Spotify','iCloud','HBO Max']} value="" onChange={name=>open('subscription',{name,currency:'CZK',next:isoDay(),card:u.cards[0]?.id,frequency:'monthly',auto:false})}/>{u.subscriptions.map(sub=>{const plan=u.plans.find(p=>p.kind==='subscription'&&p.data.id===sub.id);return <Panel key={sub.id} style={{marginTop:13}}><Row icon="repeat-outline" title={sub.name} value={fmt(sub.amount,sub.currency)} onPress={()=>open('subscription',{...sub,amount:String(sub.amount/100),auto:!!plan?.active,next:plan?.next||sub.next})}/><Label muted style={{fontSize:12,marginVertical:10}}>Další platba: {plan?.next||sub.next} · {plan?.active?'Automaticky při otevření':'Pouze evidence'}</Label><Button title={merchantBlocked(u.blockedMerchants,sub.name)?'Odblokovat obchodníka':'Zablokovat obchodníka'} secondary onPress={()=>action('block',{name:sub.name,blocked:!merchantBlocked(u.blockedMerchants,sub.name)})}/><Button title="Odebrat z evidence" secondary style={{marginTop:8}} onPress={()=>action('subscriptionDelete',{id:sub.id})}/></Panel>})}<Section title="Blokovaní obchodníci"/><Panel>{u.blockedMerchants.map(n=><Row key={n} title={n} onPress={()=>action('block',{name:n,blocked:false})}/>)}{!u.blockedMerchants.length&&<Label muted>Žádný obchodník není blokovaný.</Label>}</Panel><Label muted style={{fontSize:12,lineHeight:20,marginTop:15}}>Ceny zadáváš sám. Blokace působí na lokální karetní platby, neruší smlouvu u poskytovatele.</Label></>;
 if(section==='transfer')content=<><View style={{flexDirection:'row',gap:10}}><Button title="Nová platba" style={{flex:1}} onPress={()=>open('transfer',{currency:'CZK',frequency:'once',next:isoDay(),scheduled:false})}/><Button title="Split bill" secondary style={{flex:1}} onPress={()=>open('split',{currency:'CZK'})}/></View><Section title="Příjemci"/><Panel>{u.contacts.map(c=><Row key={c.id} icon="person-circle-outline" title={c.name} sub={c.account} onPress={()=>open('transfer',{...c,currency:'CZK',frequency:'once',next:isoDay(),scheduled:false})}/>)}{!u.contacts.length&&<Label muted>Příjemce uložíme po prvním převodu.</Label>}</Panel><Section title="Plánované platby"/>{planList('transfer')}<Section title="Rozdělené účty"/>{u.splits.map(sp=><Panel key={sp.id} style={{marginBottom:12}}><Label style={{fontWeight:'800',fontSize:19,marginBottom:10}}>{sp.name}</Label>{sp.parts.map(part=><Row key={part.id} title={part.name} sub={fmt(part.amount,sp.currency)} right={<Switch accessibilityLabel={'Uhrazeno '+part.name} value={part.paid} onValueChange={()=>action('splitPaid',{id:sp.id,part:part.id})}/>}/>)}<Button title="Sdílet rozpis" secondary onPress={()=>share(sp.name+'\n'+sp.parts.map(p=>p.name+': '+fmt(p.amount,sp.currency)).join('\n'))}/><Label muted style={{fontSize:11,lineHeight:18,marginTop:10}}>Označení uhrazeno je ruční evidence a nemění zůstatek.</Label></Panel>)}</>;
 if(section==='requests')content=<><Button title="Nová žádost o platbu" icon="qr-code-outline" onPress={()=>open('request',{currency:'CZK'})}/><Section title="Tvoje žádosti"/><Panel>{u.requests.map(r=><Row key={r.id} icon="qr-code-outline" title={fmt(r.amount,r.currency)} sub={r.note||'Žádost o platbu'} onPress={()=>open('requestDetail',r)}/>)}{!u.requests.length&&<Label muted>Zatím žádné žádosti.</Label>}</Panel></>;
 if(section==='travel')content=<><LinearGradient colors={t.mono?['#000000','#171717']:['#193F5F','#367797']} style={{padding:25,borderRadius:27,marginBottom:20}}><Icon name="airplane" color="#FFFFFF" size={42}/><Text style={{color:'#fff',fontSize:28,fontWeight:'800',marginTop:18}}>{u.travel.active?'Cesta začíná.':'Připraveno na cestu.'}</Text><Text style={{color:t.mono?'#EEEEEE':'#C9E2F4',marginTop:10}}>{u.travel.country} · {u.travel.currency}</Text></LinearGradient><Panel><Row title="Travel Mode" right={<Switch accessibilityLabel="Travel Mode" value={u.travel.active} onValueChange={v=>action('travel',{...u.travel,active:v})}/>}/><Row title="Destinace a měna" sub={u.travel.country+' · '+u.travel.currency} onPress={()=>open('travel',u.travel)}/><Row icon="wallet-outline" title="Cestovní peněženka" value={fmt(u.balances[u.travel.currency],u.travel.currency)} onPress={()=>go('wallet')}/><Row icon="options-outline" title="Země povolené na kartě" onPress={()=>go('controls')}/></Panel><Section title="ATM a směna"/><Panel><Label muted style={{lineHeight:23}}>Před potvrzením výběru zkontroluj poplatek provozovatele a nabízený kurz. Zobrazené kurzy Zenvault jsou referenční; neslouží jako živá cenová nabídka bankomatu.</Label></Panel><Section title="Pojištění a nouzové funkce"/><Panel><Row icon="shield-outline" title="Cestovní pojištění" sub="Žádná pojistka není v aplikaci sjednána."/><Row icon="snow-outline" title="Zmrazit všechny karty" onPress={()=>open('freezeAll')}/><Row icon="lock-closed-outline" title="Security Center" onPress={()=>go('security')}/></Panel></>;
 if(section==='security')content=<><Panel><Row icon="key-outline" title={u.auth?'Změna hesla':'Nastavit přihlášení heslem'} sub="E-mail / telefon a heslo místního účtu" onPress={()=>onOpen('accountPassword')}/><Row icon="lock-closed-outline" title="PIN aplikace" sub={u.security.pinConfigured?'Nastaven v zabezpečeném úložišti':'Šestimístný PIN'} onPress={()=>open('pin')}/><Row icon="scan-outline" title="Biometrie zařízení" sub={u.security.biometric?'Zapnuto':'Ověří dostupnost na zařízení'} onPress={async()=>{try{await biometric();action('security',{values:{biometric:!u.security.biometric,autoLock:!u.security.biometric||u.security.pinConfigured}});}catch(e){notice(e.message);}}}/><Row title="Zamykat po návratu" right={<Switch accessibilityLabel="Zamykat po návratu" value={u.security.autoLock} onValueChange={v=>{if(v&&!u.security.biometric&&!u.security.pinConfigured)return notice('Nejprve nastav PIN nebo ověř biometrii.');action('security',{values:{autoLock:v}});}}/>}/><Row title="Anti-phishing phrase" sub={u.security.phrase||'Vlastní rozpoznávací věta'} onPress={()=>open('phrase',{phrase:u.security.phrase})}/><Row title="Uzamknout nyní" onPress={onLock}/></Panel><Label muted style={{fontSize:12,lineHeight:20,marginTop:12}}>Face ID vyžaduje vlastní iOS build; v Expo Go není podporované. Webový náhled nemá bezpečné úložiště PINu. Zámek chrání lokální rozhraní, nejde o serverové přihlášení.</Label><Section title="Zařízení a relace"/><Panel><Row icon="phone-portrait-outline" title="Toto zařízení" sub={'Instalace '+data.installationId.slice(-6)+' · '+Platform.OS} right={<Switch accessibilityLabel="Důvěryhodné zařízení" value={u.security.trusted} onValueChange={v=>action('security',{values:{trusted:v}})}/>}/><Label muted style={{fontSize:12,lineHeight:20}}>Důvěryhodnost je lokální označení. Vzdálené relace nejsou připojené.</Label>{u.security.history.slice(0,8).map(e=><Row key={e.id} title={e.name} sub={new Date(e.date).toLocaleString('cs-CZ')}/>)}</Panel><Section title="Emergency"/><Button title="Zmrazit všechny karty" icon="snow-outline" onPress={()=>open('freezeAll')}/></>;
 if(section==='score'){const h=health(u);content=<>{stat('Financial Health',h.score===null?'Zatím bez skóre':h.score+' / 1000',h.score===null?h.reason:'Interní indikátor Zenvault. Není to úvěrové skóre.')}{h.factors?.map(fa=><Panel key={fa.name} style={{marginBottom:12}}><Row title={fa.name} value={fa.points+' / '+fa.max}/></Panel>)}<Panel><Label muted style={{lineHeight:23}}>Maximálně 500 bodů za rezervu na 3 měsíce podle minulých výdajů, 300 za zbývající část rozpočtu a 200 za alespoň 20 % rezerv ve Vaults. Výpočet nehodnotí úvěruschopnost.</Label></Panel></>;}
 if(section==='private')content=!hasPrivateBanking(u)?<Panel><Label style={{fontSize:24,fontWeight:'800'}}>Private Banking od Ultra po Prestige MAX</Label><Label muted style={{lineHeight:23,marginVertical:17}}>Osobní prostor pro tvoje požadavky, výhody a concierge.</Label><Button title="Prohlédnout tarify" onPress={()=>onOpen('tiers')}/></Panel>:<><LinearGradient colors={t.mono?['#000000','#171717']:['#0A1523','#2B425D']} style={{padding:26,borderRadius:26,marginBottom:20}}><Text style={{color:t.mono?'#FFFFFF':'#91CDFF',letterSpacing:3,fontSize:11}}>{isPrestigeTier(u.tier)?u.tier.toUpperCase()+' PRIVATE':isMax(u)?'MAX PRIVATE':u.tier==='Unlimited'?'UNLIMITED ∞ PRIVATE':u.tier==='Ultra MAX'?'ULTRA MAX PRIVATE':'ULTRA PRIVATE'}</Text><Text style={{color:'#fff',fontSize:30,fontWeight:'800',marginTop:15}}>Čas pro velké plány.</Text><Text style={{color:'#C1D0E0',lineHeight:22,marginTop:12}}>Tvoje požadavky, přehled a priority v jednom prostoru.</Text></LinearGradient><Panel>{(isPrestigeTier(u.tier)?['Osobní manager · '+u.tier,'Priority support · '+u.tier,'Family office','Privátní cestování','Lifestyle concierge','VIP zážitky']:isMax(u)?['Osobní manager · MAX','Priority support · MAX','Travel concierge','Lifestyle concierge','Zážitky a rezervace']:['Osobní manager','Priority support','Travel concierge']).map(k=><Row key={k} icon="chatbubble-outline" title={k} sub="Připravit požadavek" onPress={()=>open('service',{kind:k})}/>)}<Row icon="gift-outline" title="Exclusive offers" sub={(100*CASHBACK[u.tier])+' % u vybraných lokálních obchodníků'} onPress={()=>go('rewards')}/><Row icon="speedometer-outline" title="Správa vyšších limitů" onPress={()=>go('controls')}/></Panel><Section title="Moje požadavky"/><Panel>{u.serviceRequests.map(r=><Row key={r.id} title={r.kind} sub={r.message+' · '+r.status+(r.priority?' · Priorita '+r.priority:'')}/>)}{!u.serviceRequests.length&&<Label muted>Zatím bez požadavků.</Label>}</Panel><Label muted style={{fontSize:12,lineHeight:20,marginTop:12}}>Požadavky zůstávají v profilu. Osobní bankéř ani odesílání podpůrnému týmu nejsou připojené.</Label></>;
 if(section==='business'){const s=monthStats(u);content=!hasBusinessTools(u)?<Panel><Label style={{fontSize:25,fontWeight:'800'}}>Business na vyžádání</Label><Label muted style={{lineHeight:22,marginVertical:18}}>Individuální podmínky, firemní dashboard, karty týmu a Hologram Limited zdarma.</Label><Button title="Vyžádat nabídku" onPress={()=>onOpen('business')}/>{data.mode==='Administrátor'&&!u.parentId&&<Button style={{marginTop:12}} title="Nastavit Business tomuto profilu" secondary onPress={()=>action('businessActivate',{target:u.id})}/>}</Panel>:<>{stat('Čisté cashflow tento měsíc',fmt(s.income-s.expense),'Příjmy '+fmt(s.income)+' · výdaje '+fmt(s.expense))}<Panel style={{marginBottom:18}}><Label style={{fontSize:18,fontWeight:'800'}}>Hologram Limited máš zdarma</Label><Label muted style={{lineHeight:21,marginVertical:12}}>Exkluzivní chromový design je součástí tvého plánu Business. Žádné body navíc.</Label><Button title="Získat kartu zdarma" onPress={()=>go('gallery')}/></Panel><Button title="Přidat kartu zaměstnance" icon="add" onPress={()=>open('employee')}/><Section title="Týmové karty"/><Panel>{u.cards.filter(c=>c.owner).map(c=><Row key={c.id} icon="card-outline" title={c.owner} sub={'•••• '+c.last+' · limit '+fmt(c.limit)} onPress={()=>go('controls')}/>)}{!u.cards.some(c=>c.owner)&&<Label muted>Zatím žádná zaměstnanecká karta.</Label>}</Panel><Section title="Expenses" action="+ Přidat" onPress={()=>open('expense',{currency:'CZK'})}/>{u.expenses.map(e=><Panel key={e.id} style={{marginBottom:12}}><Row title={e.name} sub={e.employee+' · '+e.status} value={fmt(e.amount,e.currency)}/><View style={{flexDirection:'row',gap:8}}><Button title="Schválit" style={{flex:1}} secondary onPress={()=>action('expenseStatus',{id:e.id,status:'Schváleno'})}/><Button title="Zamítnout" style={{flex:1}} secondary onPress={()=>action('expenseStatus',{id:e.id,status:'Zamítnuto'})}/></View></Panel>)}<Label muted style={{fontSize:12,lineHeight:20,marginTop:12}}>Expenses jsou evidence nákladů. Schválení samo neposílá platbu, aby se výdaj nezaúčtoval dvakrát.</Label></>;}
 if(section==='junior')content=u.parentId?empty('Junior účet spravuje rodič ze svého profilu.'):<><Button title="Vytvořit Zenvault Junior" icon="add" onPress={()=>open('juniorCreate')}/><Section title="Rodinné účty"/>{data.users.filter(c=>c.parentId===u.id).map(c=><Panel key={c.id} style={{marginBottom:14}}><Row icon="person-circle-outline" title={c.name} sub={'Denní limit '+fmt(c.juniorLimit)} value={fmt(c.balances.CZK)} onPress={()=>open('juniorLimit',{target:c.id,limit:String(c.juniorLimit/100)})}/><View style={{flexDirection:'row',gap:8}}><Button title="Poslat kapesné" style={{flex:1}} onPress={()=>open('juniorTransfer',{target:c.id})}/><Button title="Pravidelně" style={{flex:1}} secondary onPress={()=>open('juniorPlan',{target:c.id,next:isoDay(),frequency:'weekly',name:c.name})}/></View></Panel>)}<Section title="Pravidelné kapesné"/>{planList('junior')}<Label muted style={{fontSize:12,lineHeight:20,marginTop:15}}>Junior je lokální podúčet. Peníze se přesouvají mezi rodičem a dítětem. Přepínač profilů není oddělené serverové oprávnění.</Label></>;
 if(section==='gallery')content=<><Chips items={tiers.map(t=>tierLabel(t.name))} value={tierLabel(galleryTier)} onChange={label=>GT(tiers.find(t=>tierLabel(t.name)===label).name)}/><Chips items={['Virtuální','Fyzická']} value={kind} onChange={K}/>{isUnlimitedTier(galleryTier)?<Panel style={{marginTop:16,marginBottom:20}}><Label style={{fontSize:22,fontWeight:'800'}}>{tierLabel(galleryTier)} Card Builder</Label><Label muted style={{lineHeight:23,marginVertical:13}}>{isPrestigeTier(galleryTier)?'Vlastní Prestige kolekce + 22 Unlimited / MAX motivů. Art Editions za 899 Kč za kartu.':galleryTier===MAX_TIER?'22 motivů v ceně a 3 Art Editions za 899 Kč za kartu.':'12 motivů Unlimited Collection.'} Vlastní zobrazené číslo, kompozice a Hologram nebo Static okraj.</Label>{renderCard({tier:galleryTier,type:kind,builder:{motif:defaultBuilderMotif(galleryTier).id,edge:'hologram',layout:'full'},last:'0000',network:'Mastercard'})}<Button title={isPrestigeTier(galleryTier)?'Otevřít '+galleryTier+' Atelier':galleryTier===MAX_TIER?'Otevřít MAX Atelier':'Otevřít Unlimited Studio'} style={{marginTop:16}} onPress={()=>go(builderRoute(galleryTier))}/></Panel>:<><Label muted style={{lineHeight:22,marginVertical:12}}>{COLLECTION_NAMES[galleryTier]} · {galleryTier}. Tři vlastní ilustrace, které nenajdeš v jiném tarifu. V ceně aktuálního tarifu; ostatní kolekce mají náhled.</Label>{[0,1,2].map(i=><View key={i} style={{marginBottom:20}}>{renderCard({tier:galleryTier,type:kind,design:i,last:'••••',network:'Mastercard'})}<Label style={{fontSize:16,fontWeight:'700',marginTop:13}}>{cardDesignName({tier:galleryTier,design:i})}</Label><Button style={{marginTop:9}} title={galleryTier===u.tier?'Přidat design '+(i+1):'Vyžaduje '+galleryTier} secondary onPress={()=>galleryTier===u.tier?action('gallery',{tier:galleryTier,cardType:kind,design:i}):onOpen('tiers')}/></View>)}</>}<Section title="Zenvault × Rolling Loud"/><Label muted style={{lineHeight:22,marginBottom:14}}>Afterhours Edition. Noční stage, palmy, neonová fialová a acid lime. Tvůj festivalový podpis.</Label>{renderCard({tier:u.tier,type:'Virtuální',design:0,edition:'rollingLoud',last:'••••',network:'Mastercard'})}<Panel style={{marginTop:16}}><Row icon="sparkles-outline" title="Speciální edice" value="1 000 bodů"/><Label muted style={{lineHeight:21,fontSize:13,marginTop:8}}>Jednorázové odemknutí designu za Zenvault Points. Dostupné ve všech plánech, včetně Business.</Label><Button style={{marginTop:15}} title={u.unlocks.includes('rollingLoud')?'Přidat Rolling Loud kartu':'Odemknout za 1 000 bodů'} onPress={()=>u.unlocks.includes('rollingLoud')?action('gallery',{tier:u.tier,cardType:'Virtuální',design:0,edition:'rollingLoud'},'Rolling Loud karta přidána.'):open('redeem',{id:'rollingLoud'})}/></Panel><Section title="Hologram Limited"/><Label muted style={{lineHeight:22,marginBottom:14}}>Prismatic Apex. Chromová dračí lebka, krystalická křídla a duhové odlesky. Samostatný design mimo tarifní kolekce.</Label><Panel style={{marginBottom:16}}><Label style={{color:t.accent,fontWeight:'800'}}>S BUSINESS, UNLIMITED MAX A PRESTIGE ZDARMA</Label><Label muted style={{marginTop:8,lineHeight:21}}>Bez odečtení bodů. Pro ostatní plány odemknutí za 500 Zenvault Points.</Label></Panel>{renderCard({tier:u.tier,type:'Virtuální',design:2,limited:true,last:'••••'})}<Button style={{marginTop:12}} title={includedReward(u,'design')?'Přidat Hologram Limited zdarma':hasLimitedAccess(u)?'Přidat Hologram Limited':'Odemknout za 500 bodů'} onPress={()=>hasLimitedAccess(u)?action('gallery',{tier:u.tier,cardType:'Virtuální',design:2,limited:true}):go('rewards')}/></>;
 if(section==='assistant')content=<><Panel><Icon name="sparkles" size={36} color={t.accent}/><Label style={{fontSize:27,fontWeight:'800',marginVertical:17}}>Zeptej se svých dat.</Label><Label muted style={{lineHeight:22}}>Lokální asistent počítá z historie tohoto profilu.</Label></Panel><View style={{marginTop:18}}><Field label="Tvoje otázka" value={query} onChangeText={Q} placeholder="Kolik jsem minul za jídlo?"/><Button title="Zeptat se" onPress={()=>A(askAssistant(u,query))}/></View><Section title="Zkus třeba"/>{['Kolik jsem minul minulý měsíc za jídlo?','Můžu tento měsíc odložit 15 000 Kč?','Kolik mám bodů?'].map(q=><Button key={q} title={q} secondary style={{marginBottom:10}} onPress={()=>{Q(q);A(askAssistant(u,q));}}/>)}{answer&&<Panel style={{marginTop:14}}><Label style={{lineHeight:25}}>{answer}</Label></Panel>}</>;
 if(section==='investments')content=<>{stat('Hodnota portfolia',fmt(u.investments.reduce((n,x)=>n+x.value*RATES[x.currency],0)),'Ruční hodnoty, přepočtené referenčním kurzem.')}<Button title="Přidat investici" icon="add" onPress={()=>open('investment',{currency:'CZK'})}/><Label muted style={{fontSize:12,lineHeight:21,marginVertical:15}}>Evidence tvého portfolia. Hodnoty zadáváš sám; zápis neprovádí nákup ani neodečítá peníze z účtu.</Label>{u.investments.map(x=><Panel key={x.id} style={{marginBottom:14}}><Row title={x.name} value={fmt(x.value,x.currency)} sub={'Aktualizováno '+isoDay(x.date)} onPress={()=>open('investment',{...x,cost:String(x.cost/100),value:String(x.value/100)})}/><Label muted style={{marginBottom:12}}>Vloženo {fmt(x.cost,x.currency)} · změna {fmt(x.value-x.cost,x.currency)}</Label><Button title={'Odebrat '+x.name} secondary onPress={()=>open('investmentDelete',x)}/></Panel>)}</>;
 if(section==='widgets')content=<><Label muted style={{lineHeight:23,marginBottom:20}}>Zapni své oblíbené widgety a uprav pořadí. Nastavení je vlastní pro každý profil. Business používá samostatný firemní přehled; osobní widgety se obnoví po přepnutí na osobní tarif.</Label><Panel>{u.widgets.map((w,i)=><View key={w.id} style={{paddingVertical:12,borderBottomWidth:1,borderColor:t.border}}><Row title={w.id} right={<Switch accessibilityLabel={'Widget '+w.id} value={w.visible} onValueChange={v=>action('widgets',{widgets:u.widgets.map(x=>x.id===w.id?{...x,visible:v}:x)})}/>}/><View style={{flexDirection:'row',gap:8}}><Button title={'Nahoru '+w.id} secondary disabled={i===0} style={{flex:1}} onPress={()=>moveWidget(i,-1)}/><Button title={'Dolů '+w.id} secondary disabled={i===u.widgets.length-1} style={{flex:1}} onPress={()=>moveWidget(i,1)}/></View></View>)}</Panel></>;
 function moveWidget(i,delta){const ws=[...u.widgets];[ws[i],ws[i+delta]]=[ws[i+delta],ws[i]];action('widgets',{widgets:ws});}
 function planList(kind){const ps=u.plans.filter(p=>p.kind===kind);return <><Panel>{ps.map(p=><View key={p.id}><Row title={p.name} sub={p.next+' · '+FRACTIONS[p.frequency]+' · '+({scheduled:'Naplánováno',paid:'Zaúčtováno',failed:'Neprovedeno',cancelled:'Zrušeno'}[p.status]||p.status)} onPress={()=>kind==='transfer'?open('transfer',{...p.data,amount:String(p.data.amount/100),planId:p.id,next:p.next,frequency:p.frequency,scheduled:true}):open(kind==='vault'?'autoVault':'juniorPlan',{...p.data,amount:String(p.data.amount/100),planId:p.id,next:p.next,frequency:p.frequency,name:p.name})}/>{p.error&&<Label style={{color:'#C3574E',fontSize:12,marginBottom:8}}>{p.error}</Label>}{p.active&&<Button title={'Zrušit '+p.name} secondary onPress={()=>action('planCancel',{id:p.id})}/>}</View>)}{!ps.length&&<Label muted>Zatím žádné příkazy.</Label>}</Panel><Label muted style={{fontSize:11,lineHeight:18,marginTop:12}}>Příkazy se provádějí při otevření aplikace. Po neúspěchu lze příkaz upravit; stejný neúspěch se automaticky neopakuje v témže dni.</Label></>;}
 function modalBody(){
  if(modal==='investment')return <>{field('name','Název investice')}{currency()}{field('cost','Vložená částka',{keyboardType:'decimal-pad'})}{field('value','Aktuální hodnota',{keyboardType:'decimal-pad'})}<Button title="Uložit investici" onPress={()=>submit({type:'investmentSave',...form,cost:cents(form.cost),value:cents(form.value)})}/></>;
  if(modal==='investmentDelete')return <><Label style={{marginBottom:20}}>Odebrat {form.name} z evidence?</Label><Button title="Potvrdit odebrání" onPress={()=>submit({type:'investmentDelete',id:form.id})}/></>;
  if(modal==='requestDetail')return <><QR text={reqText(form)}/><Label style={{textAlign:'center',fontSize:28,fontWeight:'800',marginVertical:20}}>{fmt(form.amount,form.currency)}</Label><Label muted style={{textAlign:'center',lineHeight:22,marginBottom:18}}>QR obsahuje text žádosti. Není to bankovní platební QR ani online platební odkaz.</Label><Button title="Sdílet žádost" onPress={()=>share(reqText(form))}/></>;
  if(modal==='countries')return <><Label muted style={{lineHeight:22,marginBottom:15}}>Prázdný výběr znamená všechny země v nabídce.</Label>{COUNTRIES.map(c=><Row key={c} title={c} right={<Switch value={form.countries.includes(c)} onValueChange={v=>f('countries',v?[...form.countries,c]:form.countries.filter(x=>x!==c))}/>}/>)}<Button title="Uložit země" onPress={()=>submit({type:'controls',id:form.id,values:{countries:form.countries}})}/></>;
  if(modal==='freezeAll')return <><Label style={{fontSize:21,fontWeight:'700',marginBottom:15}}>Zmrazit všech {u.cards.length} karet?</Label><Label muted style={{lineHeight:22,marginBottom:20}}>Karetní operace tohoto profilu budou zablokované. Jednotlivé karty můžeš znovu povolit v Card Controls.</Label><Button title="Potvrdit zmrazení" onPress={()=>submit({type:'freezeAll'})}/></>;
  if(modal==='redeem'){const r=REWARDS.find(r=>r.id===form.id);return <><Label style={{fontSize:22,fontWeight:'700',marginBottom:15}}>{r.name}</Label>{r.id==='rollingLoud'&&<View style={{marginBottom:18}}>{renderCard({tier:u.tier,type:'Virtuální',design:0,edition:'rollingLoud',last:'••••'})}</View>}<Label muted style={{lineHeight:22,marginBottom:20}}>Odečteme {rewardCost(u,r)} bodů z tvých {u.points} bodů. Odměna se uloží do profilu.{r.id==='rollingLoud'?' Kartu si potom přidáš v Card Gallery.':''}</Label><Button title="Potvrdit odemknutí" onPress={()=>submit({type:'redeem',id:r.id})}/></>;}
  if(modal==='pin')return <>{u.security.pinConfigured&&field('old','Stávající PIN',{secureTextEntry:true,keyboardType:'number-pad',maxLength:6})}{field('pin','Nový PIN (6 číslic)',{secureTextEntry:true,keyboardType:'number-pad',maxLength:6})}{field('repeat','Zopakuj PIN',{secureTextEntry:true,keyboardType:'number-pad',maxLength:6})}<Button title="Uložit PIN" disabled={processing} onPress={async()=>{if(form.pin!==form.repeat)return notice('PINy se neshodují.');P(true);try{await setPin(u.id,form.pin,form.old);submit({type:'security',values:{pinConfigured:true,autoLock:true}});}catch(e){notice(e.message);}finally{P(false);}}}/></>;
  if(modal==='phrase')return <>{field('phrase','Tvoje rozpoznávací věta')}<Button title="Uložit větu" onPress={()=>submit({type:'security',values:{phrase:form.phrase||''}})}/></>;
  if(modal==='travel')return <><Chips items={COUNTRIES} value={form.country} onChange={v=>{f('country',v);f('currency',v==='US'?'USD':v==='GB'?'GBP':v==='CZ'?'CZK':'EUR');}}/><Chips items={CURRENCIES} value={form.currency} onChange={v=>f('currency',v)}/><Label muted style={{lineHeight:22,marginVertical:15}}>U země s jinou měnou jde o cestovní účet v jedné ze čtyř podporovaných měn.</Label><Button title="Uložit destinaci" onPress={()=>submit({type:'travel',...form})}/></>;
  if(modal==='service')return <>{field('message','Tvůj požadavek',{multiline:true})}<Label muted style={{lineHeight:22,marginBottom:17}}>Požadavek uložíme do profilu. Odesílání skutečnému pracovníkovi není připojené.</Label><Button title="Uložit požadavek" onPress={()=>submit({type:'serviceRequest',kind:form.kind,message:form.message})}/></>;
  if(modal==='cardLimit'||modal==='juniorLimit')return <>{modal==='cardLimit'&&<Label muted style={{lineHeight:22,marginBottom:14}}>Maximum tvého plánu: {fmt(maxCardLimit(u))} denně na kartu.</Label>}{field('limit','Denní limit v Kč')}<Button title="Uložit limit" onPress={()=>submit(modal==='cardLimit'?{type:'controls',id:form.id,values:{limit:cents(form.limit)}}:{type:'juniorLimit',target:form.target,limit:cents(form.limit)})}/></>;
  if(modal==='vaultSave')return <>{field('name','Název Vaultu')}{field('target','Cílová částka v Kč')}<View style={{flexDirection:'row',gap:8,marginVertical:10}}>{[['airplane-outline','Cestování'],['shield-outline','Rezerva'],['car-outline','Auto'],['musical-notes-outline','Festival'],['sparkles-outline','Přání']].map(([icon,label])=><Pressable key={icon} accessibilityRole="button" accessibilityLabel={label} onPress={()=>f('icon',icon)} style={{padding:13,borderRadius:15,backgroundColor:form.icon===icon?t.button:t.soft}}><Icon name={icon} color={form.icon===icon?'#fff':t.accent}/></Pressable>)}</View><View style={{flexDirection:'row',gap:14,marginVertical:18}}>{['#209ACB','#8972C6','#C66885','#459F84'].map(c=><Pressable accessibilityLabel={'Barva '+c} key={c} onPress={()=>f('color',c)} style={{width:40,height:40,borderRadius:20,backgroundColor:c,borderWidth:form.color===c?4:0,borderColor:t.text}}/>)}</View><Button title="Uložit Vault" onPress={()=>submit({type:'vaultSave',...form,target:cents(form.target)})}/></>;
  if(modal==='vaultMove'||modal==='juniorTransfer')return <>{field('amount','Částka v Kč')}<Button title="Potvrdit přesun" onPress={()=>submit({type:modal,...form,amount:cents(form.amount)})}/></>;
  if(modal==='autoVault'||modal==='juniorPlan')return <>{field('amount','Částka v Kč')}{dates()}<Button title="Uložit příkaz" onPress={()=>submit({type:'plan',id:form.planId,name:form.name,kind:modal==='autoVault'?'vault':'junior',data:{id:form.id,target:form.target,amount:cents(form.amount)},next:form.next,frequency:form.frequency})}/></>;
  if(modal==='employee'||modal==='juniorCreate')return <>{field('name',modal==='employee'?'Jméno zaměstnance':'Jméno dítěte')}{field('limit','Denní limit v Kč')}<Button title="Vytvořit" onPress={()=>submit({type:modal,name:form.name,limit:cents(form.limit)})}/></>;
  if(modal==='expense')return <>{field('name','Popis výdaje')}{field('employee','Zaměstnanec')}{currency()}{field('amount','Částka')}<Button title="Uložit expense" onPress={()=>submit({type:'expense',...form,amount:cents(form.amount)})}/></>;
  if(modal==='request')return <>{currency()}{field('amount','Částka')}{field('iban','Účet / IBAN (volitelné)')}{field('note','Poznámka')}<Button title="Vytvořit žádost" onPress={()=>submit({type:'request',currency:form.currency||'CZK',amount:cents(form.amount),iban:form.iban,note:form.note})}/></>;
  if(modal==='split')return <>{field('name','Název účtu')}{currency()}{field('amount','Celkem')}{field('people','Účastníci oddělení čárkou',{placeholder:'Já, Alex, Robin'})}<Button title="Rozdělit účet" onPress={()=>submit({type:'split',...form,amount:cents(form.amount)})}/></>;
  if(modal==='subscription')return <>{field('name','Služba')}{currency()}{field('amount','Cena')}{dates()}{cardOptions()}<Row title="Automatická lokální platba" right={<Switch accessibilityLabel="Automatická lokální platba" value={!!form.auto} onValueChange={v=>f('auto',v)}/>}/><Label muted style={{fontSize:12,lineHeight:20,marginVertical:15}}>Platba se provede až při otevření aplikace, pokud to dovolí karta a zůstatek.</Label><Button title="Uložit předplatné" onPress={()=>submit({type:'subscription',...form,amount:cents(form.amount),card:form.card||u.cards[0]?.id})}/></>;
  if(['transfer','exchange','cardPay'].includes(modal)){const n=cents(form.amount);if(review)return <><Panel><View style={{flexDirection:'row',alignItems:'center',gap:12}}>{modal==='cardPay'&&<MerchantIcon merchant={findMerchant(form.merchant)}/>}<Label muted style={{flex:1}}>{modal==='transfer'?form.name:modal==='cardPay'?form.merchant:'Směna '+form.from+' → '+form.to}</Label></View><Label style={{fontSize:29,fontWeight:'800',marginVertical:18}}>{fmt(n,modal==='exchange'?form.from:form.currency||'CZK')}</Label><Label muted>{modal==='exchange'?'Obdržíš '+fmt(Math.round(n*RATES[form.from]/RATES[form.to]),form.to):modal==='transfer'?form.account:form.country+' · '+CHANNELS[form.channel]}</Label>{form.scheduled&&<Label muted style={{marginTop:12}}>Naplánováno: {form.next} · {FRACTIONS[form.frequency]}</Label>}</Panel><Button title="Potvrdit operaci" style={{marginTop:18}} onPress={()=>{if(modal==='exchange')submit({type:'exchange',...form,amount:n});else if(modal==='cardPay')submit({type:'cardPay',...form,amount:n,card:form.card||u.cards[0]?.id});else if(form.scheduled)submit({type:'plan',id:form.planId,name:form.name,kind:'transfer',data:{name:form.name,account:form.account,note:form.note||'',currency:form.currency||'CZK',amount:n},next:form.next,frequency:form.frequency});else submit({type:'transfer',...form,amount:n});}}/><Button title="Upravit" secondary style={{marginTop:10}} onPress={()=>R(false)}/></>;
   return <>{modal==='exchange'?<><Label muted>Z měny</Label><Chips items={CURRENCIES} value={form.from} onChange={v=>f('from',v)}/><Label muted>Do měny</Label><Chips items={CURRENCIES} value={form.to} onChange={v=>f('to',v)}/></>:currency()}{modal==='transfer'&&<><View style={{flexDirection:'row',gap:12,alignItems:'center',marginBottom:20}}><Icon name="person-circle-outline" size={44} color={t.accent}/><Label style={{fontWeight:'700',fontSize:18}}>{form.name||'Nový příjemce'}</Label></View>{field('name','Příjemce')}{field('account','Účet / IBAN')}{field('note','Poznámka')}<Row title="Naplánovat platbu" right={<Switch accessibilityLabel="Naplánovat platbu" value={!!form.scheduled} onValueChange={v=>f('scheduled',v)}/>}/>{form.scheduled&&dates()}</>}{modal==='cardPay'&&<><Label muted style={{fontSize:12,marginBottom:5}}>Rychlý výběr obchodníka</Label><MerchantTemplates t={t} selected={findMerchant(form.merchant)?.id} onSelect={selectMerchant}/>{cardOptions()}<Field label="Obchodník" value={form.merchant||''} onChangeText={v=>F(x=>({...x,merchant:v,merchantId:findMerchant(v)?.id,category:findMerchant(v)?.category}))}/><Chips items={Object.values(CHANNELS)} value={CHANNELS[form.channel]} onChange={v=>f('channel',Object.keys(CHANNELS).find(k=>CHANNELS[k]===v))}/><Chips items={COUNTRIES} value={form.country} onChange={v=>f('country',v)}/></>}{field('amount','Částka')}<Button title="Pokračovat" onPress={()=>{if(!Number.isSafeInteger(n)||n<=0)return notice('Zadej platnou kladnou částku.');R(true);}}/></>;
