 <Modal visible={!!modal} transparent animationType={reduced?'none':'slide'} onRequestClose={close}><View style={{flex:1,justifyContent:'flex-end',backgroundColor:'#06142688'}}><Pressable accessibilityLabel="Zavřít formulář" onPress={close} style={{position:'absolute',top:0,left:0,right:0,bottom:0}}/><KeyboardAvoidingView behavior={Platform.OS==='ios'?'padding':undefined} style={{maxHeight:'92%',width:'100%',maxWidth:620,alignSelf:'center'}}><View style={{backgroundColor:t.bg,borderTopLeftRadius:28,borderTopRightRadius:28,flexShrink:1}}><View style={{flexDirection:'row',justifyContent:'space-between',alignItems:'center',padding:22}}><Label style={{fontWeight:'800',fontSize:23,flex:1}}>{titles[modal]}</Label><Pressable accessibilityRole="button" accessibilityLabel="Zavřít formulář" onPress={close} style={{padding:8}}><Icon name="close"/></Pressable></View><ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{paddingHorizontal:22,paddingBottom:Math.max(20,insets.bottom)+22}}>{modalBody()}</ScrollView></View></KeyboardAvoidingView>{feedback!==''&&<View pointerEvents="none" style={{position:'absolute',top:insets.top+8,left:20,right:20,backgroundColor:'#16364F',padding:16,borderRadius:16}}><Text style={{color:'#FFFFFF',fontWeight:'600',textAlign:'center'}}>{feedback}</Text></View>}</View></Modal></>;
