import React,{useMemo,useState} from 'react';
import {View,Text,Pressable,ScrollView,Modal,TextInput,Switch} from 'react-native';
import {LinearGradient} from 'expo-linear-gradient';
import {RATES,fmt,monthStats} from './engine';
import {transactionFeed} from './PaymentTiming';
import {tierLabel} from './Membership';
import {merchantForTransaction} from './MerchantCatalog';
import {MerchantIcon} from './MerchantUI';

const DAY=86400000;
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const totalCash=u=>Object.entries(u.balances||{}).reduce((n,[c,v])=>n+v*(RATES[c]||1),0);
const totalVaults=u=>(u.goals||[]).reduce((n,g)=>n+(g.saved||0),0);
const totalInvestments=u=>(u.investments||[]).reduce((n,x)=>n+(x.value||0)*(RATES[x.currency]||1),0);
export function netWorth(u){return totalCash(u)+totalVaults(u)+totalInvestments(u);}

export function financialForecast(u,now=new Date()){
 const current=monthStats(u,0,now),previous=monthStats(u,-1,now);
 const day=Math.max(1,now.getDate()),daysInMonth=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
 const observed=current.expense/day;
 const fallback=previous.expense/Math.max(1,new Date(now.getFullYear(),now.getMonth(),0).getDate());
 const daily=observed||fallback||0;
 const remainingDays=Math.max(0,daysInMonth-day);
 const upcoming=(u.subscriptions||[]).filter(s=>new Date((s.next||'')+'T12:00:00')>=new Date(now.getFullYear(),now.getMonth(),now.getDate())).reduce((n,s)=>n+(s.amount||0)*(RATES[s.currency]||1),0);
 const projectedSpend=Math.round(current.expense+daily*remainingDays+upcoming);
 const projectedBalance=Math.round(totalCash(u)-daily*remainingDays-upcoming);
 const delta=previous.expense?Math.round((current.expense/previous.expense-1)*100):null;
 return {current,previous,daily,remainingDays,upcoming,projectedSpend,projectedBalance,delta};
}

export function intelligenceItems(u){
 const f=financialForecast(u),items=[];
 if(f.delta!==null&&Math.abs(f.delta)>=12)items.push({icon:f.delta>0?'trending-up-outline':'trending-down-outline',title:f.delta>0?'Výdaje zrychlují':'Výdaje zpomalují',body:`Tento měsíc eviduješ ${Math.abs(f.delta)} % ${f.delta>0?'více':'méně'} výdajů než minulý měsíc.`});
 const budget=u.budget||0;
 if(budget&&f.projectedSpend>budget)items.push({icon:'alert-circle-outline',title:'Rozpočet může být překročen',body:`Při současném tempu vychází konec měsíce přibližně na ${fmt(f.projectedSpend)}.`});
 const changed=(u.subscriptions||[]).find(s=>(s.priceHistory||[]).length);if(changed){const h=changed.priceHistory[0];items.push({icon:'pricetag-outline',title:'Změna ceny předplatného',body:`${changed.name}: ${fmt(h.from,h.currency)} → ${fmt(h.to,h.currency)}.`});}else if((u.subscriptions||[]).length)items.push({icon:'repeat-outline',title:'Předplatná pod kontrolou',body:`Sleduješ ${(u.subscriptions||[]).length} služeb. Nejbližší známé platby jsou zahrnuté do forecastu.`});
 if((u.pendingTransfers||[]).length)items.push({icon:'time-outline',title:'Čekající převody',body:`${u.pendingTransfers.length} plateb ještě čeká na připsání.`});
 if(!items.length)items.push({icon:'sparkles-outline',title:'Finanční rytmus je klidný',body:'Jakmile přibudou další pohyby, Zenvault zvýrazní změny, opakované výdaje a rizika rozpočtu.'});
 return items.slice(0,4);
}

const ROUTES=[
 {id:'transfer',icon:'arrow-up-outline',title:'Odeslat peníze',keywords:'poslat odeslat převod platba iban kontakt'},
 {id:'requests',icon:'arrow-down-outline',title:'Vyžádat platbu',keywords:'vyzadat request qr penize'},
 {id:'cards5',icon:'card-outline',title:'Card Center 5',keywords:'karta freeze zmrazit limit atm online travel'},
 {id:'intelligence5',icon:'sparkles-outline',title:'Zenvault Intelligence',keywords:'insights forecast predikce rozpočet vydaje'},
 {id:'sharedVaults5',icon:'people-outline',title:'Shared Vaults',keywords:'vault spaces sporeni sdileni cil'},
 {id:'subscriptions5',icon:'repeat-outline',title:'Subscriptions Hub',keywords:'subscription predplatne netflix hbo spotify icloud'},
 {id:'purchase5',icon:'receipt-outline',title:'Purchase Hub',keywords:'nakup platba transakce receipt doklad refund merchant obchodnik'},
 {id:'moments5',icon:'flash-outline',title:'Zenvault Moments',keywords:'moments udalosti milniky cashback travel upgrade karta'},
 {id:'security5',icon:'shield-checkmark-outline',title:'Security Center 5',keywords:'security bezpecnost pin biometrie passkey zarizeni'},
 {id:'plans5',icon:'diamond-outline',title:'Plan Center 5',keywords:'plan tarif membership prestige unlimited business'},
 {id:'admin5',icon:'construct-outline',title:'Admin Studio 5',keywords:'admin zůstatek body transakce klient zprava'}
];

export function commandResults(u,q){
 const n=norm(q),result=[];
 ROUTES.forEach(r=>{if(!n||norm(r.title+' '+r.keywords).includes(n))result.push({...r,type:'route'});});
 (u.transactions||[]).slice(0,80).forEach(x=>{if(n&&norm(x.name+' '+x.category).includes(n))result.push({type:'transaction',id:x.id,title:x.name,sub:x.category+' · '+fmt(x.value,x.currency),item:x,icon:'receipt-outline'});});
 (u.subscriptions||[]).forEach(x=>{if(n&&norm(x.name+' predplatne').includes(n))result.push({type:'route',id:'subscriptions5',title:x.name,sub:'Předplatné · '+fmt(x.amount,x.currency),icon:'repeat-outline'});});
 (u.goals||[]).forEach(x=>{if(n&&norm(x.name+' vault').includes(n))result.push({type:'route',id:'sharedVaults5',title:x.name,sub:'Vault · '+fmt(x.saved)+' / '+fmt(x.target),icon:x.icon||'sparkles-outline'});});
 (u.cards||[]).forEach(x=>{const label=`${x.network} ${x.last} ${x.type}`;if(n&&norm(label).includes(n))result.push({type:'route',id:'cards5',title:label,sub:x.frozen?'Zmrazená':'Aktivní',icon:'card-outline'});});
 return result.slice(0,18);
}

export function CommandCenter5({visible,u,ui,onClose,onGo,onOpen,onTransaction}){
 const {t,Label,Icon}=ui,[q,setQ]=useState('');
 const items=useMemo(()=>commandResults(u,q),[u,q]);
 const choose=item=>{onClose();if(item.type==='transaction')onTransaction?.(item.item);else if(item.id==='admin5')onGo('admin5');else onGo(item.id);};
 return <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
  <View style={{flex:1,backgroundColor:'#07172ACC',paddingHorizontal:16,paddingTop:58}}>
   <Pressable accessibilityLabel="Zavřít Zenvault Command" onPress={onClose} style={{position:'absolute',top:0,left:0,right:0,bottom:0}}/>
   <View style={{width:'100%',maxWidth:690,alignSelf:'center',backgroundColor:t.bg,borderRadius:30,maxHeight:'88%',overflow:'hidden',borderWidth:1,borderColor:t.border}}>
    <LinearGradient colors={t.featureGradient} start={{x:0,y:0}} end={{x:1,y:1}} style={{padding:22}}>
     <View style={{flexDirection:'row',alignItems:'center',gap:12}}><View style={{flex:1}}><Label muted style={{fontSize:10,letterSpacing:1.8,fontWeight:'800'}}>ZENVAULT COMMAND</Label><Label style={{fontSize:27,fontWeight:'800',letterSpacing:-1,marginTop:5}}>Co chceš udělat?</Label></View><Pressable onPress={onClose} style={{padding:10,borderRadius:20,backgroundColor:t.surface}}><Icon name="close"/></Pressable></View>
     <View style={{marginTop:18,flexDirection:'row',alignItems:'center',gap:10,backgroundColor:t.surface,borderRadius:18,borderWidth:1,borderColor:t.border,paddingHorizontal:14}}><Icon name="search" size={19} color={t.muted}/><TextInput autoFocus value={q} onChangeText={setQ} placeholder="Netflix, zmrazit kartu, poslat 500…" placeholderTextColor={t.muted} style={{flex:1,color:t.text,minHeight:52,fontSize:15}}/></View>
    </LinearGradient>
    <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{padding:14,paddingBottom:28}}>
     {!q&&<View style={{flexDirection:'row',flexWrap:'wrap',gap:8,marginBottom:10}}>{['Platba','Karty','Vaults','Security'].map(x=><Pressable key={x} onPress={()=>setQ(x)} style={{backgroundColor:t.soft,borderRadius:20,paddingVertical:9,paddingHorizontal:13}}><Label style={{fontSize:12,fontWeight:'700'}}>{x}</Label></Pressable>)}</View>}
     {items.map((item,i)=><Pressable key={item.type+item.id+i} onPress={()=>choose(item)} style={({pressed})=>({flexDirection:'row',alignItems:'center',gap:12,padding:14,borderRadius:18,opacity:pressed?.6:1})}><View style={{width:42,height:42,borderRadius:15,backgroundColor:t.soft,alignItems:'center',justifyContent:'center'}}><Icon name={item.icon||'sparkles-outline'} color={t.accent}/></View><View style={{flex:1}}><Label style={{fontWeight:'700'}}>{item.title}</Label>{item.sub&&<Label muted style={{fontSize:11,marginTop:4}}>{item.sub}</Label>}</View><Icon name="arrow-forward" size={15} color={t.muted}/></Pressable>)}
     {!items.length&&<View style={{padding:25,alignItems:'center'}}><Icon name="search-outline" size={32} color={t.muted}/><Label muted style={{marginTop:12,textAlign:'center'}}>Nic jsem nenašel. Zkus obchodníka, kartu, Vault nebo akci.</Label></View>}
    </ScrollView>
   </View>
  </View>
 </Modal>;
}

const WELCOME=[
 ['sparkles','Financial Command Center','Nový Home 5 skládá peníze, forecast, karty a další kroky do jednoho prostoru.'],
 ['analytics','Zenvault Intelligence','Forecast zůstatku, výdajové změny, opakované platby a upozornění na rozpočet.'],
 ['search','Zenvault Command','Vyhledej transakci nebo napiš, co chceš udělat. Bez lovení v menu.'],
 ['people','Shared Vaults','Cíle a Spaces mohou mít členy a společný kontext přímo v profilu.'],
 ['shield-checkmark','Security Center 5','PIN, biometrie, relace a emergency controls na jednom místě.']
];
export function Welcome5({visible,ui,onDone}){
 const {t,Label,Icon}=ui,[i,setI]=useState(0),item=WELCOME[i];
 return <Modal visible={visible} animationType="fade" onRequestClose={()=>{}}><View style={{flex:1,backgroundColor:t.bg,padding:24,justifyContent:'center'}}><View style={{maxWidth:650,width:'100%',alignSelf:'center'}}><Label muted style={{fontSize:10,fontWeight:'800',letterSpacing:2.4}}>WELCOME TO</Label><Label style={{fontSize:42,fontWeight:'900',letterSpacing:-2,marginTop:7}}>Zenvault 5</Label><LinearGradient colors={t.featureGradient} start={{x:0,y:0}} end={{x:1,y:1}} style={{borderRadius:32,padding:27,marginTop:28,minHeight:300,borderWidth:1,borderColor:t.border}}><View style={{width:62,height:62,borderRadius:22,backgroundColor:t.surface,alignItems:'center',justifyContent:'center'}}><Icon name={item[0]} size={31} color={t.accent}/></View><Label style={{fontSize:28,fontWeight:'800',letterSpacing:-1,marginTop:34}}>{item[1]}</Label><Label muted style={{fontSize:14,lineHeight:23,marginTop:12}}>{item[2]}</Label></LinearGradient><View style={{flexDirection:'row',gap:7,justifyContent:'center',marginVertical:22}}>{WELCOME.map((_,n)=><View key={n} style={{width:n===i?30:7,height:7,borderRadius:8,backgroundColor:n===i?t.accent:t.soft}}/>)}</View><Pressable onPress={()=>i<WELCOME.length-1?setI(i+1):onDone()} style={{minHeight:56,borderRadius:20,backgroundColor:t.button,alignItems:'center',justifyContent:'center'}}><Text style={{color:'#fff',fontSize:15,fontWeight:'800'}}>{i<WELCOME.length-1?'Pokračovat':'Začít používat Zenvault 5'}</Text></Pressable>{i>0&&<Pressable onPress={()=>setI(i-1)} style={{padding:16,alignItems:'center'}}><Label muted style={{fontWeight:'700'}}>Zpět</Label></Pressable>}</View></View></Modal>;
}

function Metric({ui,label,value,sub,icon}){const {t,Panel,Label,Icon}=ui;return <Panel style={{flex:1,minWidth:150,padding:18}}><View style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between'}}><Label muted style={{fontSize:10,fontWeight:'800',letterSpacing:1}}>{label}</Label>{icon&&<Icon name={icon} size={17} color={t.accent}/>}</View><Label style={{fontSize:22,fontWeight:'800',letterSpacing:-.7,marginTop:10}}>{value}</Label>{sub&&<Label muted style={{fontSize:10,lineHeight:16,marginTop:6}}>{sub}</Label>}</Panel>}

export default function Zenvault5Page({section,u,data,ui,dispatch,go,onOpen,onSheet,renderCard,onTransaction}){
 const {t,Panel,Label,Button,Icon,Section,Row,Field}=ui;
 const forecast=useMemo(()=>financialForecast(u),[u]);
 const [shareVault,setShareVault]=useState(null),[member,setMember]=useState(''),[memberRole,setMemberRole]=useState('Contributor');
 const action=(type,params={},message)=>dispatch({type,...params,op:Date.now().toString(36)+Math.random().toString(36).slice(2,6)},message);
