import {validAccount,cleanAccount,appearance} from './SmartTransferModel';
import {removeMembership} from './AdminMembershipModel';
import {PRESTIGE_TIER,PRESTIGE_MAX_TIER,isPrestigeTier,prestigePlan,activatePrestige} from './PrestigePlans';
import {hasMaxBenefits,hasBusinessTools} from './Membership';
import {sendBankMessage,redeemBankOffer,confirmBankDocument,notificationAction,endUserTrial} from './BankMessages';
import {findMerchant,merchantById,merchantKey,merchantBlocked} from './MerchantCatalog';
import {CREDIT_DELAYS,paymentReason,creditDate} from './PaymentTiming';
import {normalizeHomeMode,HOME_MODES} from './HomeModes';
import {APP_THEMES,canUseTheme} from './ThemeCatalog';
import {PERSONAL_TIERS,maxCardLimit,defaultCardLimit,pointsMultiplier,hasPrivateBanking,hasDisposable,assertTierChange,activateCore,activateMax,MAX_TIER,ULTRA_MAX_TIER,isMax,isUnlimitedTier,canBuildCards} from './Membership';
import {builderMotifs,motifCharge,STATIC_EDGES,parseDisplayNumber} from './UnlimitedCatalog';
// All money is stored in minor units. Rates are fixed reference rates, not live prices.
export const RATES={CZK:1,EUR:25,USD:23,GBP:29};
export const CURRENCIES=Object.keys(RATES);
export const COUNTRIES=['CZ','SK','DE','AT','PL','FR','IT','ES','GB','US','JP'];
export const CASHBACK={Silver:0,Gold:.005,Platinum:.01,Core:.0125,Pro:.015,Ultra:.02,[ULTRA_MAX_TIER]:.025,Unlimited:.03,[MAX_TIER]:.05,[PRESTIGE_TIER]:.06,[PRESTIGE_MAX_TIER]:.08,Business:0,Junior:0};
export const PARTNERS=[{id:'market',name:'Zenvault Market',category:'Nákupy',icon:'bag-outline'},{id:'travel',name:'Zenvault Travel',category:'Doprava',icon:'airplane-outline'},{id:'cafe',name:'Zenvault Café',category:'Jídlo',icon:'cafe-outline'}];
export const REWARDS=[{id:'rollingLoud',name:'Zenvault × Rolling Loud',cost:1000},{id:'theme',name:'Motiv Candy Sky',cost:300},{id:'design',name:'Karta Hologram Limited',cost:500},{id:'boost',name:'+0,5 % na další nákup u partnera',cost:200},{id:'subscription',name:'Poukaz na subscription benefit',cost:1000}];
export const includedReward=(u,id)=>!u.parentId&&((id==='design'&&(u.tier==='Business'||hasMaxBenefits(u)))||(id==='theme'&&hasMaxBenefits(u)));
export const hasLimitedAccess=u=>includedReward(u,'design')||u.unlocks.includes('design');
export const rewardCost=(u,reward)=>includedReward(u,reward.id)?0:reward.cost;
export const WIDGETS=['Balance','Spending','Vaults','Investments','Rewards','Cards','Subscriptions'];
export const makeId=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,9);
export const parsePoints=value=>{const text=String(value??'').trim().replace(/\s/g,'');const n=Number(text);return /^\d+$/.test(text)&&Number.isSafeInteger(n)&&n>=0?n:NaN;};
export const cents=s=>{const v=String(s).trim().replace(/\s/g,'').replace(',','.');const n=Math.round(Number(v)*100);return /^\d+(\.\d{1,2})?$/.test(v)&&Number.isSafeInteger(n)?n:NaN;};
export const fmt=(n,c='CZK')=>new Intl.NumberFormat('cs-CZ',{style:'currency',currency:c,maximumFractionDigits:2}).format(n/100);
export const isoDay=(d=new Date())=>{const v=new Date(d);return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;};
export function validDay(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;const d=new Date(s+'T12:00:00');return Number.isFinite(+d)&&isoDay(d)===s;}
export function nextDay(s,freq,anchor){const d=new Date(s+'T12:00:00');if(freq==='weekly')d.setDate(d.getDate()+7);else{const day=anchor||d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));}return isoDay(d);}
const check=(v,msg)=>{if(!v)throw Error(msg);};
const positive=n=>check(Number.isSafeInteger(n)&&n>0,'Zadej kladnou částku na nejvýše dvě desetinná místa.');
const cur=c=>check(CURRENCIES.includes(c),'Nepodporovaná měna.');
const debit=(u,n,c='CZK')=>{positive(n);cur(c);check(u.balances[c]>=n,'Nedostatek prostředků.');u.balances[c]-=n;};
const credit=(u,n,c='CZK')=>{positive(n);cur(c);check(Number.isSafeInteger(u.balances[c]+n),'Částka překračuje limit.');u.balances[c]+=n;};
const record=(u,name,value,currency,kind,category,extra={},date=new Date().toISOString())=>{const x={id:makeId(),name,value,currency,kind,category,date,...extra};u.transactions.unshift(x);return x;};
export function normalizeUser(u){return {...u,homeMode:normalizeHomeMode(u.homeMode),balances:{CZK:0,EUR:0,USD:0,GBP:0,...u.balances},cards:(u.cards||[]).map(c=>({atm:true,foreign:true,countries:[],credentialVersion:1,network:'Mastercard',...c})),goals:(u.goals||[]).map(g=>{const legacy=g.sharedWith||[];const sharedMembers=(g.sharedMembers||legacy.map(name=>({name,role:'Contributor'}))).filter(x=>x&&x.name);return {...g,sharedWith:[...new Set(sharedMembers.map(x=>x.name))],sharedMembers};}),transactions:u.transactions||[],pendingTransfers:u.pendingTransfers||[],notifications:u.notifications||[],bankMessages:u.bankMessages||[],documents:u.documents||[],trialHistory:u.trialHistory||[],requests:u.requests||[],plans:u.plans||[],planLog:u.planLog||[],points:u.points||0,pointsLog:u.pointsLog||[],cashbackTotal:u.cashbackTotal||0,unlocks:u.unlocks||[],boost:u.boost||0,subscriptions:(u.subscriptions||[]).map(s=>({...s,priceHistory:s.priceHistory||[]})),blockedMerchants:u.blockedMerchants||[],contacts:u.contacts||[],splits:u.splits||[],serviceRequests:u.serviceRequests||[],expenses:u.expenses||[],investments:u.investments||[],widgets:[...(u.widgets||[]).filter(w=>WIDGETS.includes(w.id)),...WIDGETS.filter(id=>!(u.widgets||[]).some(w=>w.id===id)).map(id=>({id,visible:true}))],security:{autoLock:false,biometric:false,pinConfigured:false,phrase:'',trusted:false,history:[],...u.security},travel:{active:false,country:'GB',currency:'GBP',...u.travel},operations:u.operations||[]};}
export function migrate(d){check(d&&Array.isArray(d.users)&&d.users.length,'Úložiště neobsahuje platný profil.');return {...d,version:2,featuresVersion:5,active:d.users.some(u=>u.id===d.active)?d.active:d.users[0].id,users:d.users.map(normalizeUser),installationId:d.installationId||makeId()};}
export function isExpense(x){return x.value<0&&!['Směna','Spoření','Administrace','Junior převod'].includes(x.category)&&!['exchange','vault','internal','cashback'].includes(x.kind);}
export function monthStats(u,offset=0,now=new Date()){const start=new Date(now.getFullYear(),now.getMonth()+offset,1),end=new Date(now.getFullYear(),now.getMonth()+offset+1,1);const items=u.transactions.filter(x=>new Date(x.date)>=start&&new Date(x.date)<end);const categories={};let income=0,expense=0;for(const x of items){const n=Math.round(Math.abs(x.value)*(RATES[x.currency]||1));if(isExpense(x)){expense+=n;categories[x.category]=(categories[x.category]||0)+n;}if(x.value>0&&!['Směna','Spoření','Administrace','Junior převod'].includes(x.category)&&!['internal','cashback','exchange','vault'].includes(x.kind))income+=n;}return {items,income,expense,categories};}
export function health(u){const now=monthStats(u),prev=monthStats(u,-1);const n=u.transactions.filter(isExpense).length;const reserve=Object.entries(u.balances).reduce((a,[c,v])=>a+v*RATES[c],0)+u.goals.reduce((a,g)=>a+g.saved,0);if(n<5||!prev.expense)return {score:null,reserve,reason:'Potřebujeme alespoň 5 výdajů a výdaje z minulého měsíce.'};const months=reserve/prev.expense;const savings=u.goals.reduce((a,g)=>a+g.saved,0);const factors=[{name:'Rezerva vůči minulému měsíci',points:Math.round(Math.min(1,months/3)*500),max:500},{name:'Dodržení měsíčního rozpočtu',points:Math.round(Math.max(0,1-now.expense/(u.budget||1))*300),max:300},{name:'Podíl peněz ve Vaults',points:Math.round(Math.min(1,savings/Math.max(1,reserve)/.2)*200),max:200}];return {score:factors.reduce((a,f)=>a+f.points,0),factors,reserve,months};}
function transfer(u,a,date,d){positive(a.amount);cur(a.currency);check(a.name?.trim(),'Vyplň příjemce.');const account=cleanAccount(a.account);const target=a.target&&d?.users.find(x=>x.id===a.target);if(a.target)check(target&&target.id!==u.id,'Místní příjemce není dostupný.');else check(validAccount(account),'Vyplň platné číslo účtu nebo IBAN včetně kontrolních číslic.');let request;if(a.requestId){request=target?.requests.find(r=>r.id===a.requestId);if(target)check(request&&request.status!=='paid'&&request.status!=='cancelled'&&request.amount===a.amount&&request.currency===a.currency,'Žádost již není platná nebo se změnila.');}
 debit(u,a.amount,a.currency);if(target)credit(target,a.amount,a.currency);const extra={account,target:a.target||null,...appearance(a),reference:a.op||makeId(),requestId:a.requestId||null};record(u,target?.name||a.name.trim(),-a.amount,a.currency,'transfer',a.category||'Převod',extra,date);if(target){record(target,u.name,a.amount,a.currency,'transfer','Převod',{...extra,target:u.id},date);target.notifications.unshift({id:makeId(),title:u.name+' posílá '+fmt(a.amount,a.currency),date});if(request){request.status='paid';request.paidAt=date;}}
