function vaultMove(u,a,date){const g=u.goals.find(g=>g.id===a.id);check(g,'Vault neexistuje.');positive(a.amount);if(a.withdraw){check(g.saved>=a.amount,'Ve Vaultu není dost peněz.');credit(u,a.amount);g.saved-=a.amount;}else{check(Number.isSafeInteger(g.saved+a.amount),'Limit Vaultu.');debit(u,a.amount);g.saved+=a.amount;}record(u,g.name,a.withdraw?a.amount:-a.amount,'CZK','vault','Spoření',{},date);}
