function cardPay(u,a,date){const card=u.cards.find(c=>c.id===a.card);check(card&&!card.frozen,'Karta je zmrazená nebo neexistuje.');positive(a.amount);cur(a.currency);const channel=a.channel||'online';check(['online','atm','contactless'].includes(channel),'Neplatný druh platby.');check(card[channel]!==false,'Tento typ platby je na kartě vypnutý.');check(COUNTRIES.includes(a.country),'Vyber zemi platby.');check(a.country==='CZ'||card.foreign!==false,'Zahraniční platby jsou vypnuté.');check(!card.countries?.length||card.countries.includes(a.country),'Země není pro kartu povolená.');check(!merchantBlocked(u.blockedMerchants,a.merchant),'Obchodník je zablokovaný.');check(a.merchant?.trim(),'Vyplň obchodníka.');if(card.disposable){check(hasDisposable(u),'Jednorázová karta vyžaduje Pro, Ultra, Ultra MAX, Unlimited ∞ nebo Unlimited MAX.');check(channel==='online','Jednorázová karta je pouze pro online platby.');}
 const cz=Math.round(a.amount*RATES[a.currency]);const day=isoDay(date);const spent=u.transactions.filter(x=>x.kind==='card'&&x.cardId===card.id&&isoDay(x.date)===day).reduce((n,x)=>n+Math.round(-x.value*RATES[x.currency]),0);check(spent+cz<=Math.min(card.limit,maxCardLimit(u)),'Překročen denní limit karty.');if(u.parentId){const all=u.transactions.filter(x=>x.kind==='card'&&isoDay(x.date)===day).reduce((n,x)=>n+Math.round(-x.value*RATES[x.currency]),0);check(all+cz<=(u.juniorLimit||0),'Překročen rodičovský limit.');}
