function runPlan(d,u,p,now){const date=now.toISOString();if(p.kind==='transfer')transfer(u,p.data,date,d);else if(p.kind==='vault')vaultMove(u,p.data,date);else if(p.kind==='junior')internal(d,u,p.data,date);else if(p.kind==='subscription'){const sub=u.subscriptions.find(s=>s.id===p.data.id);check(sub,'Předplatné nenalezeno.');cardPay(u,{card:sub.card,merchant:sub.name,amount:sub.amount,currency:sub.currency,country:'CZ',channel:'online',category:'Předplatné'},date);}else throw Error('Neplatný plán.');}
function settleAdminTransfers(d,now){for(const u of d.users){const remaining=[];for(const x of [...u.pendingTransfers].sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt))){if(new Date(x.dueAt)>now){remaining.push(x);continue;}const balance=u.balances[x.currency]+x.value;if(balance<0){x.status='waitingFunds';remaining.push(x);continue;}if(!Number.isSafeInteger(balance)){x.status='blocked';remaining.push(x);continue;}u.balances[x.currency]=balance;u.transactions.unshift({...x,status:'posted',date:now.toISOString(),createdAt:x.date,settledAt:now.toISOString()});u.notifications.unshift({id:makeId(),title:'Platba '+x.name+' byla zaúčtována.',date:now.toISOString()});}u.pendingTransfers=remaining;}return d;}
function clampEntitlements(u){
 if(!canUseTheme(u,APP_THEMES.find(m=>m.id===u.appThemeId)))u.appThemeId='sky';
