function expireTrials(d,now){for(const u of d.users){if(u.planTrial&&+new Date(u.planTrial.endsAt)<=+now){endUserTrial(u,now);clampEntitlements(u);}}return d;}
export function processDue(input,now=new Date()){let d=expireTrials(JSON.parse(JSON.stringify(migrate(input))),now);settleAdminTransfers(d,now);const day=isoDay(now);for(const user of [...d.users]){for(const plan of [...user.plans]){if(!plan.active||plan.next>day)continue;let u=d.users.find(x=>x.id===user.id),p=u.plans.find(x=>x.id===plan.id);if(p.lastAttempt===day&&p.status==='failed')continue;let steps=0;while(p.active&&p.next<=day&&steps++<36){const due=p.next;const draft=JSON.parse(JSON.stringify(d));const du=draft.users.find(x=>x.id===u.id),dp=du.plans.find(x=>x.id===p.id);try{runPlan(draft,du,dp,now);dp.status='paid';delete dp.error;dp.lastAttempt=day;du.planLog.unshift({id:makeId(),plan:p.id,name:p.name,due,status:'paid',date:now.toISOString()});if(p.frequency==='once')dp.active=false;else dp.next=nextDay(p.next,p.frequency,p.anchor);d=draft;}catch(e){p.status='failed';p.lastAttempt=day;p.error=e.message;u.planLog.unshift({id:makeId(),plan:p.id,name:p.name,due,status:'failed',error:e.message,date:now.toISOString()});break;}u=d.users.find(x=>x.id===user.id);p=u.plans.find(x=>x.id===plan.id);}}}return d;}
